// N03 Validate Preflight -- the run's single fail-closed gate.
//
// Everything downstream assumes this node threw on anything wrong, so it is
// deliberately exhaustive and has no default branch. Nothing has been fetched
// and no token has been spent when it runs, which is the point: a bad proof
// card or a missing state file costs nothing to reject here and costs a bundle
// nobody can bind if it is caught later.
try {
  // EVERY lookup whose key comes from outside this workflow goes through here.
  //
  // A bare object literal indexed with an external key resolves through
  // Object.prototype, so `constructor`, `toString`, `valueOf`, `hasOwnProperty`
  // and `__proto__` are truthy members of every table. That is not theoretical
  // here: the signal-type enum gate was `if (!HYPOTHESIS_TABLE[type])`, and it is
  // the ONLY enforcement of that enum -- the tool schema declares it but the model
  // API does not validate tool input -- so `signal_event_type: "__proto__"` was
  // ADMITTED, reached the review packet a person reads, and would have raised a
  // bare KeyError inside the authority's `RELATIONSHIPS[...]`, discarding all five
  // prospects after all five had been confirmed.
  function ownProp(table, key) {
    if (table === null || table === undefined) { return undefined; }
    var k = String(key === undefined || key === null ? '' : key);
    return Object.prototype.hasOwnProperty.call(table, k) ? table[k] : undefined;
  }

  // `ownProp` returns a VALUE. Asking it a presence question -- `if (!ownProp(o, k))`
  // -- is true whenever the key is present and falsy, so `null`, `0`, `false` and
  // `''` read as absent. That is how N03's "closed" roster schema came to accept
  // any unrecognised key whose value was falsy, which is exactly the shape a
  // NEGATIVE geography fact takes: `boros_unreadable: false`, `matched_count: 0`.
  //
  // So presence gets its own function, and the two are never interchangeable again.
  function hasKey(table, key) {
    if (table === null || table === undefined) { return false; }
    return Object.prototype.hasOwnProperty.call(
      table, String(key === undefined || key === null ? '' : key));
  }

  // Strips legal suffixes and articles only. Domain nouns are never stripped --
  // removing `housing` or `services` would collide distinct organizations.
  function normKey(s) {
    var DROP = ['inc', 'incorporated', 'llc', 'llp', 'lp', 'corp', 'corporation',
      'co', 'company', 'the', 'ltd', 'limited'];
    return String(s === undefined || s === null ? '' : s)
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/&/g, ' and ')
      .replace(/[^a-z0-9]+/g, ' ')
      .trim()
      .split(' ')
      .filter(function (t) { return t && DROP.indexOf(t) === -1; })
      .join('-');
  }

  // Crockford base32, 26 chars, matching run_receipt.schema.json's
  // ^[0-9A-HJKMNP-TV-Z]{26}$ : 10 chars of a 48-bit big-endian timestamp then 16
  // random. The alphabet omits I, L, O and U by construction.
  function ulid(nowMs, rnd) {
    var A = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
    var t = Math.floor(nowMs);
    var out = '';
    for (var i = 0; i < 10; i++) { out = A[t % 32] + out; t = Math.floor(t / 32); }
    for (var j = 0; j < 16; j++) { out += A[Math.floor(rnd() * 32)]; }
    return out;
  }

  function utcDate(iso) { return String(iso === undefined || iso === null ? '' : iso).slice(0, 10); }

  function daysBetween(fromIso, toIso) {
    var a = Date.parse(String(fromIso).slice(0, 10) + 'T00:00:00Z');
    var b = Date.parse(String(toIso).slice(0, 10) + 'T00:00:00Z');
    if (isNaN(a) || isNaN(b)) { return null; }
    return Math.floor((a - b) / 86400000);
  }

  function addDays(iso, days) {
    var t = Date.parse(String(iso).slice(0, 10) + 'T00:00:00Z');
    if (isNaN(t)) { throw new Error('addDays: unparseable date'); }
    return new Date(t + days * 86400000).toISOString().slice(0, 10);
  }

  function isIsoDate(s) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) { return false; }
    var t = Date.parse(String(s) + 'T00:00:00Z');
    return !isNaN(t) && new Date(t).toISOString().slice(0, 10) === String(s);
  }

  // The ONE place that decides whether a value is a real jurisdiction.
  //
  // `business_state` decides whether an organization is in scope, and an
  // out-of-scope verdict costs 3650 days -- so what counts as "an answer" has to
  // be a MEMBERSHIP test, not a shape test. Three successive repairs of this
  // defect each closed on a list of bad values chosen to be the ones that repair
  // handled, and each time live HPD held another:
  //
  //   `null`     1,179 CorporateOwner/Agent rows. Caught by an emptiness test.
  //   `OFFICE`   5 rows -- ALLIANCE HOUSING in the Bronx, businesscity
  //              `WEST 166 STREET`: a row whose columns are shifted by one. NOT
  //              caught by an emptiness test; caught by a shape test.
  //   `NA`       1 CorporateOwner row (a Georgetown, Malaysia address), 53 rows
  //              across all roles. NOT caught by a shape test -- `/^[A-Z]{2}$/`
  //              admits 676 strings and only 59 are jurisdictions.
  //   `NU`       1 row, businesscity NEW YORK, zip 10001: a typo of NY. It sits
  //              on an Officer row, which N09 never lets speak for an
  //              organization, so it cannot reach G0 today -- it is what the
  //              class looks like, not a live instance of it. `NA` is the live
  //              instance on the G0 path.
  //
  // A membership test closes the class rather than the instance. Anything that is
  // not a jurisdiction is an ABSENT fact: held for 7 days and re-asked next run,
  // never rejected for ten years. Padding and case are normalized rather than
  // rejected, because `NY ` is New York and holding it would be its own error.
  //
  // The set is the USPS jurisdictions: 50 states, DC, the five territories, and
  // the three overseas military codes. A non-US subdivision (`ON`, `BC`) is
  // therefore an absent fact rather than a verified out-of-scope one -- the
  // conservative direction, and the cost is a repeated hold rather than a wrong
  // ten-year block.
  var US_JURISDICTIONS = ['AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA',
    'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD', 'MA', 'MI', 'MN',
    'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ', 'NM', 'NY', 'NC', 'ND', 'OH', 'OK',
    'OR', 'PA', 'RI', 'SC', 'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI',
    'WY', 'DC', 'AS', 'GU', 'MP', 'PR', 'VI', 'AA', 'AE', 'AP'];

  function stateOf(raw) {
    // Non-strings are absent, not coerced. `String(['CA'])` is 'CA', so an
    // array-valued field would manufacture a VERIFIED out-of-scope verdict and a
    // ten-year block out of a shape nobody intended. SODA returns only strings
    // and nulls today; this costs one line and removes the question.
    if (typeof raw !== 'string') { return ''; }
    var s = raw.trim().toUpperCase();
    return US_JURISDICTIONS.indexOf(s) === -1 ? '' : s;
  }

  // The ONE place that decides whether a value is a real NYC borough.
  //
  // The sibling of `stateOf`, and it exists because the geography gate has TWO
  // inputs and only one of them was ever given a membership test. `boro` was read
  // as `String(row.boro).trim().toUpperCase()` and kept if non-empty, so any value
  // HPD returned that was not a borough name -- a numeric code, a shifted column,
  // a renamed field -- entered `operating_boros` as a borough that matches none of
  // the five. The verdict then read that as "operates nowhere in NYC", which with
  // a known out-of-scope mailing state is the one input that earns 3650 days.
  //
  // The live feed holds exactly the five names today and no NULL over 203,887 rows
  // (`test/fixtures/soda/boro-vocabulary.json`), so this is the class rather than
  // a live instance -- which is precisely what `businessstate` was until HPD added
  // `NA`, then `OFFICE`, then `NU`. Closing it on the same terms costs nothing.
  //
  // Anything not a borough is an ABSENT fact, never a present one that happens to
  // be out of scope. Padding and case are normalized rather than rejected.
  var NYC_BOROUGHS = ['MANHATTAN', 'BRONX', 'BROOKLYN', 'QUEENS', 'STATEN ISLAND'];

  function boroOf(raw) {
    // Non-strings are absent, not coerced -- `String(['BRONX'])` is 'BRONX', and a
    // one-element array is exactly the shape a carry bug produces.
    if (typeof raw !== 'string') { return ''; }
    var up = raw.trim().toUpperCase();
    return NYC_BOROUGHS.indexOf(up) === -1 ? '' : up;
  }

  var REQUIRED_FILES = ['discovery-config.json', 'seed-roster.json', 'proof-card.json',
    'protected-clients.json', 'discovery-ledger.json', 'carryover.json', 'frame-cursor.json'];

  var DENIED_FLOOR = ['zoominfo.com', 'rocketreach.co', 'apollo.io', 'theorg.com',
    'leadiq.com', 'ziprecruiter.com', 'indeed.com', 'glassdoor.com', 'linkedin.com'];

  var items = $input.all();

  // readWriteFile read emits json.fileName and NO json.filePath (captured;
  // section 8 N01 claims otherwise). Key on fileName only.
  var byName = {};
  for (var i = 0; i < items.length; i++) {
    var name = items[i].json.fileName;
    if (typeof name !== 'string' || name === '') {
      throw new Error('preflight-file-unnamed at index ' + i);
    }
    if (byName[name] !== undefined) { throw new Error('preflight-file-duplicated: ' + name); }
    byName[name] = items[i].json.parsed;
  }

  for (var f = 0; f < REQUIRED_FILES.length; f++) {
    if (!(REQUIRED_FILES[f] in byName)) {
      throw new Error('preflight-file-missing: ' + REQUIRED_FILES[f]);
    }
    if (byName[REQUIRED_FILES[f]] === undefined || byName[REQUIRED_FILES[f]] === null) {
      throw new Error('preflight-file-unparsed: ' + REQUIRED_FILES[f]);
    }
  }
  var extra = Object.keys(byName).filter(function (k) { return REQUIRED_FILES.indexOf(k) === -1; });
  if (extra.length > 0) { throw new Error('preflight-file-unexpected: ' + extra.join(',')); }

  var config = byName['discovery-config.json'];
  var roster = byName['seed-roster.json'];
  var proofCard = byName['proof-card.json'];
  var protectedClients = byName['protected-clients.json'];
  var ledger = byName['discovery-ledger.json'];
  var carryover = byName['carryover.json'];
  var cursor = byName['frame-cursor.json'];

  // --- 2. config shape ---------------------------------------------------
  if (config.schema_version !== 'c2-discovery-config-v1') {
    throw new Error('config-schema-version-unexpected: ' + config.schema_version);
  }
  function need(obj, keyPath, type) {
    var parts = keyPath.split('.');
    var cur = obj;
    for (var k = 0; k < parts.length; k++) {
      if (cur === null || typeof cur !== 'object' || !(parts[k] in cur)) {
        throw new Error('config-key-missing: ' + keyPath);
      }
      cur = cur[parts[k]];
    }
    if (type === 'number' && typeof cur !== 'number') { throw new Error('config-key-not-a-number: ' + keyPath); }
    if (type === 'string' && typeof cur !== 'string') { throw new Error('config-key-not-a-string: ' + keyPath); }
    if (type === 'boolean' && typeof cur !== 'boolean') { throw new Error('config-key-not-a-boolean: ' + keyPath); }
    if (type === 'array' && !Array.isArray(cur)) { throw new Error('config-key-not-an-array: ' + keyPath); }
    return cur;
  }
  need(config, 'cohort_id', 'string');
  need(config, 'mode', 'string');
  need(config, 'paths.root', 'string');
  need(config, 'paths.contact_universe_dir', 'string');
  need(config, 'paths.contact_universe_pattern', 'string');
  need(config, 'heartbeat.enabled', 'boolean');
  need(config, 'heartbeat');
  need(config, 'gates.max_signal_age_days', 'number');
  need(config, 'gates.proof_card_max_age_days', 'number');
  need(config, 'gates.max_page_bytes', 'number');
  need(config, 'gates.max_contact_page_bytes', 'number');
  need(config, 'gates.quote_span_max_words', 'number');
  need(config, 'gates.required_cohort_size', 'number');
  need(config, 'frame.page_size', 'number');
  need(config, 'frame.min_buildings', 'number');
  need(config, 'frame.max_buildings', 'number');
  need(config, 'caps.max_orgs_per_run', 'number');
  need(config, 'caps.max_domain_candidates_per_org', 'number');
  need(config, 'caps.max_pages_per_org', 'number');
  need(config, 'http.user_agent', 'string');
  need(config, 'model.id', 'string');
  need(config, 'mission_control.write', 'boolean');
  need(config, 'mission_control.base_url', 'string');
  need(config, 'denied_hosts', 'array');

  // The authority's own clocks, transcribed. G4 being LOOSER than the gate does
  // not produce a lenient run, it produces a full bundle that is then rejected --
  // so a config that drifts above these is a fatal misconfiguration, not a
  // preference. jt-ops:scripts/cohort_two_authority.py:
  //   MAX_SOURCE_AGE    = 30 days  (proof card AND every source retrieval)
  //   MAX_ADMISSION_AGE = 24 hours (the receipt's verified_at)
  var AUTHORITY_MAX_SOURCE_AGE_DAYS = 30;
  if (config.gates.proof_card_max_age_days > AUTHORITY_MAX_SOURCE_AGE_DAYS) {
    throw new Error('proof-card-window-exceeds-authority: config ' +
      config.gates.proof_card_max_age_days + 'd > admit ' + AUTHORITY_MAX_SOURCE_AGE_DAYS + 'd');
  }
  // The authority hard-codes `if len(WORD_RE.findall(quote)) > 25`. Nothing
  // bounded this config value against it, and since the count moved onto the
  // COMMITTED span it decides admissibility: at 26 the lane admits a quote
  // admit rejects -- all five prospects, after a person confirmed all five.
  var AUTHORITY_MAX_QUOTE_WORDS = 25;
  if (typeof config.gates.quote_span_max_words !== 'number' ||
      config.gates.quote_span_max_words > AUTHORITY_MAX_QUOTE_WORDS) {
    throw new Error('quote-span-words-exceeds-authority: config ' +
      config.gates.quote_span_max_words + ' > admit ' + AUTHORITY_MAX_QUOTE_WORDS);
  }
  // The verified-channel owner reads the contact surface itself with a 512 KiB
  // ceiling, so a larger page passes G3 here and fails there.
  var AUTHORITY_MAX_CONTACT_BYTES = 524288;
  if (config.gates.max_contact_page_bytes > AUTHORITY_MAX_CONTACT_BYTES) {
    throw new Error('contact-page-cap-exceeds-authority: config ' +
      config.gates.max_contact_page_bytes + ' > owner ' + AUTHORITY_MAX_CONTACT_BYTES);
  }

  // heartbeat.ping_url is required to be a real string ONLY when enabled, so the
  // disabled default stays valid. A true flag against a disabled N43H would
  // report health that does not exist, so both must move together.
  if (config.heartbeat.enabled === true) {
    if (typeof config.heartbeat.ping_url !== 'string' || config.heartbeat.ping_url === '') {
      throw new Error('heartbeat-enabled-without-ping-url');
    }
  }

  // --- 3. denied hosts is a superset of the barred list -------------------
  for (var d = 0; d < DENIED_FLOOR.length; d++) {
    if (config.denied_hosts.indexOf(DENIED_FLOOR[d]) === -1) {
      throw new Error('denied-hosts-incomplete: ' + DENIED_FLOOR[d]);
    }
  }

  // --- protected clients --------------------------------------------------
  if (protectedClients.schema_version !== 'outreach-protected-clients-v1') {
    throw new Error('protected-clients-schema-version-unexpected');
  }
  if (!Array.isArray(protectedClients.names) || protectedClients.names.length === 0) {
    throw new Error('protected-clients-empty');
  }

  // --- state files --------------------------------------------------------
  if (!ledger || typeof ledger !== 'object') { throw new Error('ledger-absent'); }
  // Every other preflight file fails closed on a wrong schema_version; these two
  // did not, and they are the two a foreign writer touches.
  if (ledger.schema_version !== 'c2-discovery-ledger-v1') {
    throw new Error('ledger-schema-version-unexpected: ' + JSON.stringify(ledger.schema_version));
  }
  if (carryover && carryover.schema_version !== 'c2-discovery-carryover-v1') {
    throw new Error('carryover-schema-version-unexpected: ' +
      JSON.stringify(carryover.schema_version));
  }
  if (!Array.isArray(ledger.entries)) { throw new Error('ledger-entries-not-an-array'); }
  // One row per organization. N41 writes the ledger through a merge that
  // DEDUPLICATES by org_key, and then writes the watermark from the merged
  // length -- so a file carrying duplicates passes both watermark gates on the
  // way in and comes out with a watermark above the row count it was written
  // from. The next run then fails `ledger-entries-shrank` forever, naming the
  // wrong cause: nothing was lost, the writer deduplicated. A hand recovery that
  // appends a corrected row beside the original is exactly how duplicates get
  // there, and that is the case the watermark exists for.
  //
  // Refused here so `entries.length` and "distinct organizations" are the same
  // number at both ends of the comparison.
  var seenLedgerKey = {};
  for (var lk = 0; lk < ledger.entries.length; lk++) {
    var lrow = ledger.entries[lk];
    // NOT trimmed. N41's mergeLedger keys on the raw `e.org_key`, so trimming
    // here would make `'alpha'` and `' alpha'` one row to this guard and two to
    // the writer -- a run stopped on a ledger the merge would have handled. The
    // two must key identically or the guard protects a different file.
    var lkey = lrow && typeof lrow.org_key === 'string' ? lrow.org_key : '';
    if (!lkey) { continue; }   // the §3a table below names this one properly
    if (ownProp(seenLedgerKey, lkey)) {
      throw new Error('ledger-entry-duplicated: ' + lkey);
    }
    seenLedgerKey[lkey] = true;
  }

  // `isFinite` and an integer test, not just `>= 0`. `1e400` is valid JSON,
  // parses to Infinity, passes `typeof === 'number'` and `>= 0`, and then no row
  // count can ever satisfy the guard -- a permanent stall, reported at N06
  // rather than at the node whose whole job is to refuse before anything is
  // fetched. `cursor.offset` twenty lines down already does this.
  function badWatermark(v) {
    return typeof v !== 'number' || !isFinite(v) || !(v >= 0) || Math.floor(v) !== v;
  }
  if (ledger.exclusion_watermark &&
      typeof ledger.exclusion_watermark.universe_records === 'number' &&
      badWatermark(ledger.exclusion_watermark.universe_records)) {
    // A negative watermark makes `rows.length < watermark` unreachable, so the
    // contact-universe-shrank guard -- whose whole job is the un-burn direction
    // -- never fires again. N41 only ever writes Math.max, so this arrives by
    // hand or from a foreign writer.
    throw new Error('ledger-watermark-negative: ' +
      ledger.exclusion_watermark.universe_records);
  }
  if (!ledger.exclusion_watermark || typeof ledger.exclusion_watermark.universe_records !== 'number') {
    throw new Error('ledger-watermark-missing');
  }
  // The SECOND exclusion source needs the same protection, and did not have it.
  // The universe watermark covers organizations jt-ops knows about, which an
  // organization only joins after a real send. Between this lane emitting a
  // cohort and that send happening, the ONLY thing standing between an emitted
  // organization and a second contact is its ledger row -- so a ledger that
  // loses rows re-contacts exactly the organizations the universe cannot yet
  // cover. Truncation, a partial write, or a foreign rewrite all land here.
  if (typeof ledger.exclusion_watermark.ledger_entries !== 'number') {
    throw new Error('ledger-entries-watermark-missing');
  }
  if (badWatermark(ledger.exclusion_watermark.ledger_entries)) {
    throw new Error('ledger-entries-watermark-negative: ' +
      ledger.exclusion_watermark.ledger_entries);
  }
  if (!Array.isArray(carryover.prospects)) { throw new Error('carryover-prospects-not-an-array'); }
  if (cursor.schema_version !== 'c2-frame-cursor-v1') {
    throw new Error('cursor-schema-version-unexpected: ' + JSON.stringify(cursor.schema_version));
  }
  if (typeof cursor.offset !== 'number' || cursor.offset < 0 ||
      !isFinite(cursor.offset) || Math.floor(cursor.offset) !== cursor.offset) {
    throw new Error('cursor-offset-invalid: ' + JSON.stringify(cursor.offset));
  }
  if (cursor.dataset !== 'tesw-yqqr') { throw new Error('cursor-dataset-unexpected'); }

  var startedAt = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
  var asOf = startedAt.slice(0, 10);

  // --- 3a. Every FOREIGN-AUTHORED field a burn decision reads ------------
  //
  // Enumerated in ONE table rather than hardened one field at a time. Three
  // review cycles found the same defect three times -- the ledger key, then the
  // outcome, then the key's PRESENCE -- each a field of a record this workflow
  // does not write, reaching a burn decision unvalidated. Every one of them
  // failed OPEN: the unreadable value meant "not burned", so an organization
  // that had already been contacted was contacted again.
  //
  // The rule for this table: if a field can change whether an organization is
  // excluded, it is listed here, and anything this lane cannot read stops the
  // run. Adding a branch on a foreign field without adding it here is the
  // defect; the test walks this list rather than one scenario per field.
  var LEDGER_OUTCOMES = ['emitted', 'contacted', 'held', 'rejected', 'carryover',
    'domain-unresolved'];

  function blank(v) {
    return v === undefined || v === null ||
      (typeof v === 'string' && v.trim() === '');
  }
  function needString(where, row, field) {
    if (typeof row[field] !== 'string' || blank(row[field])) {
      throw new Error(where + '-' + field + '-invalid: ' + JSON.stringify(row[field]));
    }
  }
  function checkRows(where, rows, fields) {
    for (var ri = 0; ri < rows.length; ri++) {
      var row = rows[ri];
      if (!row || typeof row !== 'object' || Array.isArray(row)) {
        throw new Error(where + '-entry-not-an-object: index ' + ri);
      }
      for (var fi = 0; fi < fields.length; fi++) { fields[fi](where, row, ri); }
    }
  }

  checkRows('ledger', ledger.entries, [
    // The key the whole exclusion comparison is made on. Missing, blank or
    // non-string reached N06's `continue` -- the un-burn direction -- and N41
    // then dropped the row from the next write, erasing the record of the send.
    function (where, row) { needString(where, row, 'org_key'); },
    // The only field that puts a row INTO the burned set.
    function (where, row) {
      var out = blank(row.outcome) ? '' : String(row.outcome).trim().toLowerCase();
      if (LEDGER_OUTCOMES.indexOf(out) === -1) {
        throw new Error('ledger-outcome-unrecognised: ' + JSON.stringify(row.org_key) +
          ' has outcome ' + JSON.stringify(row.outcome));
      }
    },
    // Compared LEXICOGRAPHICALLY against run.as_of, so a different date format
    // silently compares wrong and releases the organization. Absent is allowed
    // and means "no recheck window"; present and unreadable is not.
    function (where, row) {
      if (row.recheck_after === undefined || row.recheck_after === null) { return; }
      if (typeof row.recheck_after !== 'string' || !isIsoDate(row.recheck_after)) {
        throw new Error('ledger-recheck_after-invalid: ' + JSON.stringify(row.org_key) +
          ' has recheck_after ' + JSON.stringify(row.recheck_after) +
          ' (compared as a string against ' + asOf + ', so it must be YYYY-MM-DD)');
      }
    },
    // Also added to the exclusion set when present.
    function (where, row) {
      if (row.domain === undefined || row.domain === null) { return; }
      if (typeof row.domain !== 'string' || blank(row.domain)) {
        throw new Error('ledger-domain-invalid: ' + JSON.stringify(row.domain));
      }
    }
  ]);

  if (!carryover || typeof carryover !== 'object') { throw new Error('carryover-absent'); }
  if (!Array.isArray(carryover.prospects)) { throw new Error('carryover-prospects-not-an-array'); }
  checkRows('carryover', carryover.prospects, [
    // Not an exclusion source since r12, but it is still keyed, counted and
    // written back; a keyless row is a queued prospect silently lost.
    function (where, row) { needString(where, row, 'org_key'); }
  ]);

  // --- 3b. G0 input: the seed roster's geography --------------------------
  //
  // Validated HERE, in the preflight, because everything it protects happens
  // later: the first public fetch, the first model call, and the first ledger
  // write all come after this node. A run that cannot evaluate its own roster
  // must cost nothing and change nothing.
  //
  // WHY THIS GATE EXISTS. G0 rejects on `business_state`, and that value reaches
  // it from the HPD CONTACTS feed. A roster-only organization -- one the frame
  // did not surface on this page -- used to arrive with '' and be rejected
  // `out-of-scope-geography`, a verdict about a fact the run never had. That
  // reason code carries a 3650-day recheck window, so one zero-contacts run
  // wrote ledger entries blocking the entire roster for ten years (FINDINGS,
  // "D4 residual"). The roster now carries the fact; this refuses to start
  // without it. Missing geography is NOT out of scope and is NOT a default --
  // it is an unanswerable question, and the run stops.
  if (!roster || typeof roster !== 'object') { throw new Error('seed-roster-absent'); }
  if (roster.schema_version !== 'c2-seed-roster-v1') {
    throw new Error('seed-roster-schema-version-unexpected: ' + roster.schema_version);
  }
  if (!Array.isArray(roster.organizations)) { throw new Error('seed-roster-organizations-not-an-array'); }

  for (var ro = 0; ro < roster.organizations.length; ro++) {
    var rorg = roster.organizations[ro];
    var rname = rorg && typeof rorg.name === 'string' ? rorg.name.trim() : '';
    if (!rname) { throw new Error('seed-roster-entry-unnamed: index ' + ro); }
    if (rorg.geography_unresolved) {
      throw new Error('seed-roster-geography-unresolved: ' + rname + ' -- ' +
        String(rorg.geography_unresolved.reason || 'no reason recorded'));
    }
    var geo = rorg.geography;
    if (!geo || typeof geo !== 'object') {
      throw new Error('seed-roster-geography-missing: ' + rname);
    }
    // An ENUMERATED schema, not a hand-maintained list of checks.
    //
    // Five review cycles moved the burn decision one field further out --
    // `business_state`, then `boro`, then the registration count, then the array
    // behind the count -- and each time this loop was extended by hand, one field
    // behind the decision. The policy line says roster geography is "validated
    // completely before any fetch, model call, or ledger write"; while the check
    // was a list of field names somebody remembered to add, that was not true.
    //
    // So the schema is the contract: every key is named, every key is typed, and
    // a key that is NOT named is refused. Adding a field to the geography
    // decision without adding it here is now impossible rather than merely
    // discouraged -- an unrecognised key stops the run instead of being carried
    // silently to whatever reads it next.
    function bad(suffix) {
      throw new Error('seed-roster-geography-malformed: ' + rname + ' ' + suffix);
    }
    function isUrl(v) { return typeof v === 'string' && v.indexOf('https://') === 0; }
    // A date has to be a STRING that parses, not anything String() can coerce
    // into one: `Date.parse(String(0))` is 2000-01-01, so a bare `0` passed as a
    // verified-at timestamp. These fields carry WHEN a fact was checked, and a
    // date nobody wrote is not an answer.
    function isDate(v) { return typeof v === 'string' && !isNaN(Date.parse(v)); }
    function strArray(v, rule, label, arrayLabel) {
      if (!Array.isArray(v)) { bad((arrayLabel || label) + ' is not an array'); }
      var seenOne = {};
      for (var q = 0; q < v.length; q++) {
        if (!rule(v[q])) { bad(label + '=' + JSON.stringify(v[q])); }
        var kq = String(v[q]);
        // A duplicate inflates a count without adding evidence. That matters for
        // `matched_registration_ids`, which is now an input to the burn decision.
        if (ownProp(seenOne, kq)) { bad(label + ' repeats ' + JSON.stringify(v[q])); }
        seenOne[kq] = true;
      }
    }
    // Each entry: [required, check]. The `check` throws its own message where a
    // caller already depends on the wording, and returns false otherwise.
    var GEO_SCHEMA = {
      // Through stateOf, not a private copy of the rule. A lower-case or padded
      // value would compare unequal in G0 and read as out of scope, and a
      // two-letter non-jurisdiction (`XX`, `NU`) would read as a VERIFIED
      // out-of-scope state and cost 3650 days. A roster fact is hand-resolved by
      // a person, so this is the one that has to be strict: stored exactly as
      // stateOf would return it, or refused.
      business_state: [true, function (v) {
        if (typeof v !== 'string' || stateOf(v) === '' || stateOf(v) !== v) {
          bad('business_state=' + JSON.stringify(v));
        }
        return true;
      }],
      // `boroOf`, not a private list -- a second copy of a membership rule is a
      // rule that drifts.
      boros: [true, function (v) {
        strArray(v, function (x) { return boroOf(x) === x; }, 'boro', 'boros');
        return true;
      }],
      // The registration evidence. This is the field that decides whether an
      // empty borough list reads as "operates nowhere in NYC" (3650 days) or as
      // "holds NYC buildings we could not place" (7 days), so it is required and
      // its CONTENTS are checked: a missing field, a string, a number or a
      // padded array of junk each used to reduce silently to a count and buy or
      // defeat a decade block. `geographyVerdict` made its own argument
      // un-defaultable for exactly this reason; that is worth nothing if the
      // value reaching it defaulted one layer up.
      matched_registration_ids: [true, function (v) {
        strArray(v, function (x) { return /^[0-9]+$/.test(String(x)) && typeof x === 'string'; },
          'matched_registration_id');
        return true;
      }],
      source: [true, function (v) {
        if (typeof v !== 'string' || v === '') {
          throw new Error('seed-roster-geography-unsourced: ' + rname);
        }
        return true;
      }],
      retrieved_at: [true, function (v) {
        if (!isDate(v)) { throw new Error('seed-roster-geography-undated: ' + rname); }
        return true;
      }],
      // JT's policy of 2026-09-17 clause 1: a roster fact carries a source a
      // reader can re-run and the moment it was verified.
      geography_source_url: [true, function (v) {
        if (!isUrl(v)) {
          throw new Error('seed-roster-geography-source-url-missing: ' + rname);
        }
        return true;
      }],
      geography_verified_at: [true, function (v) {
        if (!isDate(v)) {
          throw new Error('seed-roster-geography-verified-at-missing: ' + rname);
        }
        return true;
      }],
      // The BOROUGH claim needs its own citation. `geography_source_url` is the
      // contacts query; it carries `businessstate` and cannot carry `boro`.
      boros_source_url: [true, function (v) {
        if (!isUrl(v)) {
          throw new Error('seed-roster-boros-source-url-missing: ' + rname);
        }
        return true;
      }],
      // Provenance the derivation records. Not inputs to any decision, but named
      // so the schema stays closed; anything unnamed is refused below.
      selection_rule: [false, function (v) { return typeof v === 'string' && v !== ''; }],
      selected_from: [false, function (v) {
        return !!(v && typeof v === 'object' && !Array.isArray(v));
      }],
      observed_business_states: [false, function (v) {
        strArray(v, function (x) { return typeof x === 'string'; }, 'observed_business_state');
        return true;
      }],
      matched_corporation_names: [false, function (v) {
        strArray(v, function (x) { return typeof x === 'string' && x !== ''; },
          'matched_corporation_name');
        return true;
      }],
      contact_rows: [false, function (v) {
        return typeof v === 'number' && isFinite(v) && v >= 0 && Math.floor(v) === v;
      }]
    };
    // `hasKey`, not `ownProp`. `ownProp` returns the VALUE, so `!ownProp(geo, k)`
    // was true for every key present with a falsy value -- and the loop below
    // then skipped it without ever asking whether the schema names it. The
    // "closed" schema was open for `null`, `0`, `false` and `''`, which is
    // precisely how a negative geography fact would be written.
    for (var gk in GEO_SCHEMA) {
      if (!hasKey(GEO_SCHEMA, gk)) { continue; }
      var spec = GEO_SCHEMA[gk];
      if (!hasKey(geo, gk)) {
        if (!spec[0]) { continue; }
        // Run the check on `undefined` rather than reporting absence generically.
        // Several of these throw a bespoke message that callers and tests depend
        // on -- `seed-roster-boros-source-url-missing` names the field and the
        // organization -- and a missing field should read the same as a malformed
        // one to whoever has to fix it.
        spec[1](undefined);
        bad(gk + ' is absent');
      }
      // `!== true`, not `=== false`. A check that returns a falsy NON-boolean --
      // `v && typeof v === 'object'` returns `null` for a null input -- would
      // otherwise pass. Every check returns a strict boolean or throws.
      if (spec[1](geo[gk]) !== true) { bad(gk + '=' + JSON.stringify(geo[gk])); }
    }
    for (var gk2 in geo) {
      if (!hasKey(geo, gk2)) { continue; }
      if (!hasKey(GEO_SCHEMA, gk2)) {
        bad('unrecognised key ' + JSON.stringify(gk2) + ' -- add it to GEO_SCHEMA ' +
          'in N03 before anything is allowed to read it');
      }
    }
    // An entry kept on the roster asserts its identity was confirmed. One that
    // records the opposite must not be a candidate at all.
    // Present-and-not-`true` is unverified. `=== false` alone let the STRING
    // "false", `0` and `null` read as verified, which fails toward contacting an
    // organization whose identity was explicitly left unconfirmed. Absent stays
    // acceptable: the shipped entries do not carry the key, and the three that
    // record `identity_verified: false` are held in the file's `removed` list.
    if (hasKey(rorg, 'identity_verified') && rorg.identity_verified !== true) {
      throw new Error('seed-roster-identity-unverified: ' + rname);
    }
    // N09 keys every candidate on normKey(name) and silently drops an entry that
    // normalizes to nothing -- a name made only of dropped corporate tokens
    // ("The Inc") would sit on the roster looking present and never be evaluated.
    if (normKey(rname) === '') {
      throw new Error('seed-roster-entry-unkeyable: ' + JSON.stringify(rname));
    }
  }

  // --- 4. G4, the run-level proof-card gate -------------------------------
  // Any failure aborts the WHOLE run: zero fetches, zero LLM calls, zero cost.
  // One card licenses the whole niche, so there is no per-prospect variant.
  function proofFail(clause) { throw new Error('proof-card-invalid: ' + clause); }
  if (!proofCard || typeof proofCard !== 'object') { proofFail('absent'); }
  if (proofCard.schema_version !== 'proof-asset-card-v1') { proofFail('schema_version'); }
  if (proofCard.status !== 'verified') { proofFail('status'); }
  if (proofCard.verified_by !== 'jt') { proofFail('verified_by'); }
  if (typeof proofCard.card_id !== 'string' || proofCard.card_id === '') { proofFail('card_id'); }
  if (typeof proofCard.system_revision !== 'string' || proofCard.system_revision === '') {
    proofFail('system_revision');
  }
  var verifiedAt = Date.parse(String(proofCard.verified_at));
  if (isNaN(verifiedAt)) { proofFail('verified_at'); }
  if (!Array.isArray(proofCard.facts) || proofCard.facts.length < 1) { proofFail('facts'); }
  var licensedConcepts = 0;
  for (var c = 0; c < proofCard.facts.length; c++) {
    var fact = proofCard.facts[c];
    if (!fact || typeof fact !== 'object' || Array.isArray(fact)) { proofFail('facts[' + c + ']-not-an-object'); }
    if (typeof fact.fact_id !== 'string' || fact.fact_id === '') { proofFail('facts[].fact_id'); }
    if (typeof fact.outbound_text !== 'string' || fact.outbound_text === '') {
      proofFail('facts[].outbound_text');
    }
    if (!Array.isArray(fact.claim_values)) { proofFail('facts[].claim_values'); }
    for (var v = 0; v < fact.claim_values.length; v++) {
      if (!/^(?:[$£€]?\d[\d,.]*%?)$/.test(String(fact.claim_values[v]))) {
        proofFail('facts[].claim_values');
      }
    }
    if (fact.concept_id === 'coi-reminder-routing' && fact.sentence_id === 'coi-reminder-routing-v1') {
      licensedConcepts++;
    }
  }
  if (licensedConcepts < 1) { proofFail('no-licensed-fact'); }
  var ageDays = daysBetween(asOf, new Date(verifiedAt).toISOString().slice(0, 10));
  if (ageDays === null) { proofFail('age'); }
  if (ageDays < 0 || ageDays > config.gates.proof_card_max_age_days) { proofFail('age'); }

  // --- 5. Mission Control preconditions -----------------------------------
  // A card with no dollars scores 0 in the deterministic ranker and never
  // surfaces, so a write with a null value is worse than no write at all.
  if (config.mission_control.write === true) {
    if (typeof config.mission_control.dollars !== 'number' || !isFinite(config.mission_control.dollars)) {
      throw new Error('mission-control-dollars-required-when-write-enabled');
    }
    if (typeof config.mission_control.stage_probability !== 'number' ||
        !isFinite(config.mission_control.stage_probability)) {
      throw new Error('mission-control-stage-probability-required-when-write-enabled');
    }
    var base = String(config.mission_control.base_url);
    if (base.indexOf('http://127.0.0.1') !== 0 && base.indexOf('http://localhost') !== 0) {
      throw new Error('mission-control-base-url-not-local');
    }
  }

  // --- 6. mode -------------------------------------------------------------
  if (config.mode !== 'dry-run' && config.mode !== 'live') {
    throw new Error('mode-invalid: ' + config.mode);
  }

  var runId = ulid(Date.now(), Math.random);
  if (!/^[0-9A-HJKMNP-TV-Z]{26}$/.test(runId)) { throw new Error('run-id-malformed'); }

  var universePath = config.paths.contact_universe_dir + '/' +
    String(config.paths.contact_universe_pattern).replace('{DATE}', asOf);

  return [{
    json: {
      run: {
        run_id: runId,
        cohort_id: config.cohort_id,
        as_of: asOf,
        started_at: startedAt,
        mode: config.mode,
        out_dir: config.paths.root + '/out/' + runId,
        contact_universe_path: universePath
      },
      config: config,
      roster: roster,
      proof_card: proofCard,
      protected_clients: protectedClients,
      ledger: ledger,
      carryover: carryover,
      cursor: cursor
    }
  }];
} catch (e) { throw new Error('N03: ' + e.message); }

// N06 Build Exclusion Index -- the G1 authority.
//
// The failure direction that matters here is NOT "throws too often". It is an
// exclusion source that parses to nothing and silently suppresses nobody, which
// is what lesson #132's DNC defect did: a populated Do Not Contact tab produced
// an empty key set and every listed tenant got emailed, with the daily summary
// rendering "Do not contact: 0" exactly as if the list were empty.
try {
  // EVERY lookup whose key comes from outside this workflow goes through here.
  //
  // A bare object literal indexed with an external key resolves through
  // Object.prototype, so `constructor`, `toString`, `valueOf`, `hasOwnProperty`
  // and `__proto__` are truthy members of every table. That is not theoretical
  // here: the signal-type enum gate was `if (!HYPOTHESIS_TABLE[type])`, and it is
  // the ONLY enforcement of that enum -- the tool schema declares it but the model
  // API does not validate tool input -- so `signal_event_type: "__proto__"` was
  // ADMITTED, reached the review packet a person reads, and would have raised a
  // bare KeyError inside the authority's `RELATIONSHIPS[...]`, discarding all five
  // prospects after all five had been confirmed.
  function ownProp(table, key) {
    if (table === null || table === undefined) { return undefined; }
    var k = String(key === undefined || key === null ? '' : key);
    return Object.prototype.hasOwnProperty.call(table, k) ? table[k] : undefined;
  }

  // Strips legal suffixes and articles only. Domain nouns are never stripped --
  // removing `housing` or `services` would collide distinct organizations.
  function normKey(s) {
    var DROP = ['inc', 'incorporated', 'llc', 'llp', 'lp', 'corp', 'corporation',
      'co', 'company', 'the', 'ltd', 'limited'];
    return String(s === undefined || s === null ? '' : s)
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/&/g, ' and ')
      .replace(/[^a-z0-9]+/g, ' ')
      .trim()
      .split(' ')
      .filter(function (t) { return t && DROP.indexOf(t) === -1; })
      .join('-');
  }

  // The same logical column arrives under different key spellings from different
  // producers (#132 proved it on a live instance), and a silently-undefined key
  // in an exclusion source means "suppress nobody".
  //
  // A value present under a correct alias but of the WRONG TYPE is drift, not an
  // absence, and it must not be coerced: `String({legal:'Quarry Hill'})` is
  // 'object-object' after normKey, `String(123)` is '123', `String(true)` is
  // 'true' -- each a non-empty string, so each counted as a USABLE exclusion key
  // while excluding nobody, and the "any unusable row is fatal" guard could not
  // see it. Measured: a contacted organization back in the cohort, no error.
  // Every call site of this helper reads a name or a key, so a non-string is
  // always drift; it throws rather than returning something the caller will
  // happily use.
  function firstFilled(obj, aliases) {
    if (!obj) { return undefined; }
    for (var i = 0; i < aliases.length; i++) {
      var v = obj[aliases[i]];
      if (v === undefined || v === null) { continue; }
      if (typeof v !== 'string') {
        throw new Error('foreign-field-not-a-string: ' + aliases[i] + '=' +
          JSON.stringify(v) + ' (' + (Array.isArray(v) ? 'array' : typeof v) + ')');
      }
      if (v.trim() !== '') { return v; }
    }
    return undefined;
  }

  // The CONTAINER alias, and it must not be firstFilled: String([]) is '', so a
  // legitimately empty array reads as blank and the caller concludes the key is
  // absent. On an exclusion source that is the difference between "a first run
  // with an empty ledger" and "throw", so it gets its own helper with an explicit
  // Array.isArray test.
  // AMBIGUITY IS NOT RESOLVABLE HERE. firstFilled treats a present-but-wrong
  // FIELD as drift and throws; this decides which array IS the source, and
  // picking one by preference order is worse than picking a wrong field -- it
  // silently discards an entire exclusion list. Measured: a producer emitting a
  // legacy `records` alongside the live `prospects` dropped every contacted
  // organization, with `loaded/usable` reading 1/1 and no counter moving, and an
  // already-contacted organization went back into the cohort with a full review
  // packet and a ledger row saying this lane emitted it.
  //
  // That is not hypothetical for the 63 prospects currently in flight: the
  // shipped ledger is empty, so the contacted universe is their ONLY exclusion
  // source, and one extra container key drops all 63 at once.
  //
  // So: exactly one alias may be present. More than one is a producer this lane
  // cannot read, and a present alias that is not an array is drift.
  function firstArray(obj, aliases) {
    if (!obj) { return undefined; }
    var found = [];
    for (var i = 0; i < aliases.length; i++) {
      var v = obj[aliases[i]];
      if (v === undefined || v === null) { continue; }
      if (!Array.isArray(v)) {
        throw new Error('foreign-container-not-an-array: ' + aliases[i] + ' is ' +
          (typeof v));
      }
      found.push(aliases[i]);
    }
    if (found.length > 1) {
      throw new Error('foreign-container-ambiguous: ' + found.join(' and ') +
        ' are both present, and which one is the source cannot be guessed');
    }
    return found.length === 1 ? obj[found[0]] : undefined;
  }

  // A single shared token from COMMON_TOKENS is NOT a near match -- this is the
  // `living` / `health` regex-artifact class JT cleared on 2026-09-09.
  var COMMON_TOKENS = ['housing', 'community', 'services', 'service', 'health', 'living',
    'group', 'center', 'centre', 'association', 'management', 'properties', 'property',
    'realty', 'urban', 'new', 'york', 'nyc', 'city', 'jersey', 'american', 'national',
    'family', 'families', 'home', 'homes', 'care'];

  var ROLE_ALLOWLIST = ['property management', 'property and asset', 'asset management',
    'portfolio operations', 'housing operations', 'director of housing', 'facilities',
    'compliance', 'operations'];

  var SEGMENT_PHRASES = ['permanent supportive housing', 'supportive housing',
    'transitional housing', 'homeless services', 'sro', 'congregate care'];

  var PM_PHRASES = ['property management', 'residential management', 'asset management'];

  var TIER_B_PLUS = ['compliance', 'qicompliance', 'operations', 'propertymanagement',
    'propertymgmt', 'assetmanagement', 'housingoperations', 'facilities'];

  // Tier C is a REJECTION, not a low rank: an operations message landing in a
  // recruiting inbox reads as a vendor mismatch and is discarded before it reaches
  // anyone who owns the problem.
  var TIER_C = ['recruiting', 'recruitingmanagers', 'careers', 'jobs', 'hr',
    'humanresources', 'development', 'communications', 'press', 'media', 'donate',
    'giving', 'volunteer'];

  var OPENERS = ['dated-observation', 'condition-first', 'direct-question-context',
    'operational-contrast'];
  var CLOSINGS = ['open-process', 'timing', 'standardization', 'routing'];

  function utcDate(iso) { return String(iso === undefined || iso === null ? '' : iso).slice(0, 10); }

  function daysBetween(fromIso, toIso) {
    var a = Date.parse(String(fromIso).slice(0, 10) + 'T00:00:00Z');
    var b = Date.parse(String(toIso).slice(0, 10) + 'T00:00:00Z');
    if (isNaN(a) || isNaN(b)) { return null; }
    return Math.floor((a - b) / 86400000);
  }

  function addDays(iso, days) {
    var t = Date.parse(String(iso).slice(0, 10) + 'T00:00:00Z');
    if (isNaN(t)) { throw new Error('addDays: unparseable date'); }
    return new Date(t + days * 86400000).toISOString().slice(0, 10);
  }

  function isIsoDate(s) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) { return false; }
    var t = Date.parse(String(s) + 'T00:00:00Z');
    return !isNaN(t) && new Date(t).toISOString().slice(0, 10) === String(s);
  }

  // N04/N05 replace $json with file metadata (lesson #25), so the preflight
  // payload is read from its node by reference rather than from the item.
  var pre = $('N03 Validate Preflight').first().json;
  var run = pre.run;
  var config = pre.config;
  var ledger = pre.ledger;
  var carryover = pre.carryover;
  var protectedClients = pre.protected_clients;

  var universe = $input.first().json.universe;
  if (!universe || typeof universe !== 'object') { throw new Error('contact-universe-unparsed'); }

  // The daily preflight writes its rows under `prospects`; older artifacts used
  // `records`. Read through an alias for the CONTAINER as well as for the
  // fields -- a container key the producer does not use throws on .length, and
  // a guard that never runs is not a guard.
  var rows = firstArray(universe, ['records', 'prospects']);
  if (rows === undefined) { throw new Error('contact-universe-rows-not-an-array'); }

  // generated_at is naive (no Z) from this producer, so compare date prefixes
  // rather than parsing the whole value.
  if (utcDate(universe.generated_at) !== utcDate(run.as_of)) {
    throw new Error('contact-universe-stale: generated_at=' + utcDate(universe.generated_at) +
      ' as_of=' + utcDate(run.as_of));
  }

  // Lesson #134: a filtered export is a snapshot, not a roster. A SHRINKING
  // exclusion set would un-burn an organization already contacted, which is the
  // unsafe direction, so it is fatal rather than a warning.
  var watermark = ledger.exclusion_watermark.universe_records;
  if (rows.length < watermark) {
    throw new Error('contact-universe-shrank: ' + rows.length + ' < watermark ' + watermark);
  }

  var COMPANY_ALIASES = ['company', 'organization', 'organization_name', 'name'];
  var SLUG_ALIASES = ['slug', 'client_slug', 'prospect_slug'];

  var exact = {};
  function addExact(key) { if (key && key.length > 0) { exact[key] = true; } }

  // Per-source counters. Per-source is the whole point: #132's defect was that
  // both checks derived from ONE array, so the "second check" failed with the
  // first. A second check on the same input is not defense in depth -- the
  // per-source guard is what makes G1 safe.
  var health = {
    universe_records_loaded: rows.length, universe_records_usable: 0,
    ledger_entries_loaded: 0, ledger_entries_usable: 0,
    carryover_loaded: 0, carryover_usable: 0,
    protected_names_loaded: 0, protected_names_usable: 0
  };

  var tokens = {};
  function addTokens(key) {
    var parts = key.split('-');
    for (var t = 0; t < parts.length; t++) {
      if (!parts[t] || COMMON_TOKENS.indexOf(parts[t]) !== -1) { continue; }
      // ownProp, because the token comes from an organization NAME in an
      // exclusion source. normKey lowercases and strips to [a-z0-9-], which
      // leaves `constructor` intact -- and tokens['constructor'] is then a
      // function, so .indexOf(key) is not a function and the run dies with a
      // message naming neither the source nor the name.
      if (ownProp(tokens, parts[t]) === undefined) { tokens[parts[t]] = []; }
      var bucket = ownProp(tokens, parts[t]);
      if (bucket.indexOf(key) === -1) { bucket.push(key); }
    }
  }

  for (var i = 0; i < rows.length; i++) {
    var company = firstFilled(rows[i], COMPANY_ALIASES);
    var slug = firstFilled(rows[i], SLUG_ALIASES);
    var usable = false;
    if (company !== undefined) {
      var ck = normKey(company);
      if (ck) { addExact(ck); addTokens(ck); usable = true; }
    }
    if (slug !== undefined) {
      var sk = String(slug).trim().toLowerCase();
      if (sk) { addExact(sk); usable = true; }
    }
    if (usable) { health.universe_records_usable++; }
  }

  var ledgerEntries = Array.isArray(ledger.entries) ? ledger.entries : [];
