  // universe cannot: an organization this lane emitted is excluded by its ledger
  // row alone until jt-ops records a send. Fewer rows than we have ever written
  // means rows were lost, and the un-burn direction is fatal, not a warning.
  if (ledgerEntries.length < ledger.exclusion_watermark.ledger_entries) {
    throw new Error('ledger-entries-shrank: ' + ledgerEntries.length +
      ' < watermark ' + ledger.exclusion_watermark.ledger_entries);
  }
  health.ledger_entries_loaded = ledgerEntries.length;
  var recheckBlocked = {};
  for (var l = 0; l < ledgerEntries.length; l++) {
    var e = ledgerEntries[l];
    var ek = firstFilled(e, ['org_key']);
    if (ek === undefined) { continue; }
    health.ledger_entries_usable++;
    // NORMALIZED as well as verbatim. The universe path runs every company
    // name through normKey; this path did not, and N09 compares against
    // normKey(corporationname) -- so a ledger key differing only in case or
    // spacing missed the burned union entirely and the organization was
    // selected for outreach again. Measured: `quarry-hill-supportive` blocks,
    // `QUARRY-HILL-SUPPORTIVE` and `Quarry Hill Supportive` do not. It defeats
    // the near-match backstop too, because jaccard() splits on '-' and compares
    // case-sensitively.
    //
    // This matters most for the one outcome this workflow never writes:
    // `contacted` arrives from jt-ops after a real send, so its key shape is
    // authored elsewhere -- which is exactly where a mismatch is likely and
    // where the cost is contacting someone twice.
    var ekNorm = normKey(ek);
    // The OUTCOME is normalized for the same reason the key is, and it was not:
    // `outcome` is the only thing that puts a row into the burned set, and on a
    // `contacted` row it is authored by jt-ops, not here. Measured before this:
    // `contacted` blocked, while `Contacted`, `CONTACTED`, `' contacted'` and
    // `Emitted` each re-selected an already-contacted organization for outreach,
    // and latest-wins then overwrote the jt-ops row, erasing the record of the
    // first send. An unrecognised value is refused in N03 rather than silently
    // un-burning here.
