      addExact(String(ek));
      if (ekNorm) { addExact(ekNorm); }
      if (e.domain) { addExact(String(e.domain).toLowerCase()); }
    }
    if (e.recheck_after && String(e.recheck_after) > String(run.as_of)) {
      recheckBlocked[String(ek)] = String(e.recheck_after);
      if (ekNorm) { recheckBlocked[ekNorm] = String(e.recheck_after); }
    }
