  // passed every gate and was cut only because the cohort was already full. It
  // has not been contacted. Adding it to the burned union made N09 reject it
  // `burned-pool-duplicate`, which N30 prices at 3650 days, and N41's
  // latest-wins merge then overwrote the run-1 `carryover` row with a decade
  // block -- so the very next run permanently burned an organization the
  // previous run had deliberately saved. Measured as a two-run pair; with
  // caps.max_orgs_per_run at 40 against required_cohort_size 5, one healthy run
  // can queue 35 of them.
  //
  // Nothing about double-contact depends on this. An organization that really
  // was contacted is excluded independently, twice over: by the contacted
  // universe above, and by the ledger's `emitted`/`contacted` outcomes below.
  // Carryover is a strict subset of "evaluated and NOT selected".
  var carryRows = Array.isArray(carryover.prospects) ? carryover.prospects : [];
  health.carryover_loaded = carryRows.length;
  for (var cy = 0; cy < carryRows.length; cy++) {
    var ck2 = firstFilled(carryRows[cy], ['org_key']);
    if (ck2 === undefined) { continue; }
    health.carryover_usable++;
  }

  var names = Array.isArray(protectedClients.names) ? protectedClients.names : [];
  health.protected_names_loaded = names.length;
  for (var p = 0; p < names.length; p++) {
    // Typed, for the same reason the universe rows are: `normKey(123)` is '123'
    // and `normKey({n:'Altmark'})` is 'object-object' -- both non-empty, both
    // counted usable, and neither protects the client they name.
    if (typeof names[p] !== 'string') {
      throw new Error('protected-client-not-a-string: index ' + p + ' is ' +
