    health.protected_names_usable++;
    addExact(pk);
    addTokens(pk);
  }

  health.universe_records_unusable = health.universe_records_loaded - health.universe_records_usable;
  health.ledger_entries_unusable = health.ledger_entries_loaded - health.ledger_entries_usable;
