      config: config,
      roster: pre.roster,
      proof_card: pre.proof_card,
      cursor: pre.cursor,
      exclusion: { exact: Object.keys(exact), tokens: tokens },
      recheck: { blocked: recheckBlocked },
      exclusion_health: health
    }
  }];
} catch (e) { throw new Error('N06: ' + e.message); }

