  // the cursor, so a page that comes back full is the ordinary case and N30
  // advances past it. A contacts-style page sentry here would fail every healthy
  // run. The argument is stated rather than omitted so the decision is visible
  // at the call site and a future read cannot inherit "no sentry" by accident.
  var registrations = sodaRows($input.all(), 'registrations', null);

  var ids = [];
  for (var i = 0; i < registrations.length; i++) {
