  // end), and N08 must still run once so the chain does not stall.
  if (out.length === 0) {
    out.push({
      json: {
        chunk_index: 0, registration_ids: [],
        where_clause: "registrationid in ('0')",
        registrations: [], rows_returned: 0,
        page_size: pre.config.frame.page_size, run: pre.run
