      // Without ownProp this reads Object.prototype.constructor -- truthy, with
      // a `length` of 1 -- so a real organization is HELD near-match-requires-jt
      // and the packet tells JT it matches `undefined`. A spurious hold can take
      // the run below five, and five is all-or-nothing.
      var owners = ownProp(idx.exclusion.tokens, parts[t]);
      if (owners && owners.length > 0) {
        matchedOn = { arm: 'shared-uncommon-token', token: parts[t], against: owners[0] };
      }
    }
    if (!matchedOn) {
      for (var e2 = 0; e2 < idx.exclusion.exact.length && !matchedOn; e2++) {
        var other = idx.exclusion.exact[e2];
        if (other.indexOf('-') === -1 && other === cand.org_key) { continue; }
        if (jaccard(cand.org_key, other) >= 0.5) {
          matchedOn = { arm: 'jaccard', token: null, against: other };
        }
      }
    }
    if (matchedOn) {
      nearMatches.push({
        org_key: cand.org_key, organization_name: cand.organization_name,
        decision: 'HELD', reason_code: 'near-match-requires-jt',
        matched_arm: matchedOn.arm, matched_token: matchedOn.token, matched_against: matchedOn.against
      });
      continue;
    }
    survivors.push(cand);
  }

  survivors.sort(function (a, b) {
    if (a.from_roster !== b.from_roster) { return a.from_roster ? -1 : 1; }
    if (a.portfolio_units !== b.portfolio_units) { return b.portfolio_units - a.portfolio_units; }
    return a.org_key < b.org_key ? -1 : (a.org_key > b.org_key ? 1 : 0);
  });

  var capped = survivors.slice(0, config.caps.max_orgs_per_run);
  for (var cut = config.caps.max_orgs_per_run; cut < survivors.length; cut++) {
    skipped.push({ org_key: survivors[cut].org_key, organization_name: survivors[cut].organization_name,
      decision: 'SKIP', reason_code: 'max-orgs-per-run-cap' });
  }

  var denied = {};
  for (var dh = 0; dh < config.denied_hosts.length; dh++) { denied[String(config.denied_hosts[dh]).toLowerCase()] = true; }

  var out = [];
  for (var o = 0; o < capped.length; o++) {
    var cand2 = capped[o];
    var compact = cand2.org_key.replace(/-/g, '');
    var hosts = [compact + '.org', compact + '.com', cand2.org_key + '.org'];
    var unique = [];
    for (var h = 0; h < hosts.length && unique.length < config.caps.max_domain_candidates_per_org; h++) {
      if (unique.indexOf(hosts[h]) === -1) { unique.push(hosts[h]); }
    }
    for (var u3 = 0; u3 < unique.length; u3++) {
      // A barred host reaching the fetch plan is a defect, not a filterable
      // input: cohort one recorded a vendor naming a compliance director who
      // does not appear on the organization's own leadership page.
      if (denied[unique[u3]]) { throw new Error('denied-host-in-fetch-plan: ' + unique[u3]); }
      // Decided HERE, not at G0. G0 runs in N26, which is after the page fetch
      // and after the Anthropic call, so a verdict reached there has already
      // been paid for. JT's policy requires a mailing-state conflict to cost no
      // model call, and the facts needed to see one -- the registrations'
      // boroughs and the contact row's state -- are both present in this node.
      // G0 recomputes the same verdict from the same function; this is the
      // early exit, not a second opinion.
      // The third argument separates a candidate whose borough column we could
      // not read from one that genuinely operates nowhere in NYC.
      // `portfolio_units` is the HPD operating evidence this organization is
      // known to hold -- buildings on this run's frame page, or the roster's
      // recorded registration matches, whichever is larger. > 0 means it is in
      // the city's building registration file, and therefore operates here as a
      // matter of record whatever the borough column said.
      var verdict = geographyVerdict(cand2.operating_boros, cand2.business_state,
        cand2.portfolio_units);
      out.push({
        json: {
          run_id: run.run_id,
          org_key: cand2.org_key,
          prospect_id: 'c2-' + cand2.org_key,
          organization_name: cand2.organization_name,
          portfolio_units: cand2.portfolio_units,
          business_state: cand2.business_state,
          // Not `|| []`. Every candidate reaching here was built with an array,
          // so this only ever fires on a defect -- and turning that into an
          // empty list would price it as "no operating evidence", which is the
          // one input that earns the decade block. Asserted in the suite rather
          // than left to the comment: restoring the default used to ship green.
          operating_boros: cand2.operating_boros,
          from_roster: cand2.from_roster,
          candidate_host: unique[u3],
          candidate_index: u3,
          decision: verdict.decision,
          reason_code: verdict.reason_code,
          geography_detail: verdict.detail,
          _sentinel: false
        }
      });
    }
  }

  // R4: a connection carrying zero items does not fire, and an empty fan-out
  // would silently skip BOTH branches including the convergence one. The
  // sentinel keeps the spine alive; every work-branch filter drops it.
  if (out.length === 0) {
    out.push({ json: { _sentinel: true, run_id: run.run_id } });
  }

  // N09D interpolates run_id and prospect_id into an Execute Command string, so
  // both are screened HERE, before anything reaches a shell. The helper screens
  // them again independently -- but a value that could not survive this check
  // must never be built in the first place, and a failure is fatal rather than
  // filtered, because an unsafe identifier is a defect in the derivation and not
  // an input to sanitise around.
  for (var chk = 0; chk < out.length; chk++) {
    var cj = out[chk].json;
    if (!/^[0-9A-HJKMNP-TV-Z]{26}$/.test(String(cj.run_id))) {
      throw new Error('run-id-unsafe-for-shell');
    }
    if (cj._sentinel !== true && !/^c2-[a-z0-9]+(?:-[a-z0-9]+)*$/.test(String(cj.prospect_id))) {
      throw new Error('prospect-id-unsafe-for-shell: ' + String(cj.prospect_id));
    }
  }

  // Carried for N13/N21/N25/N30, which read this node by reference.
  out[0].json._frame_summary = {
    registrations_returned: registrations.length,
    last_registration_date_seen: lastDateSeen,
    organizations_seen: candidates.length,
    survivors: capped.length,
    skipped: skipped,
    near_matches: nearMatches
  };
  return out;
} catch (e) { throw new Error('N09: ' + e.message); }

// N10B Normalize Homepage Fetch.
//
// An HTTP Request node replaces $json with its response (lesson #25), so the
// candidate_host is gone by N10's output. Identity is restored by INDEX
// ALIGNMENT against the filter that fed the fetch, and the alignment is
// ASSERTED rather than assumed: N10 uses a non-array responseFormat and
// therefore emits exactly one output item per input item, in input order. If
// that ever stops being true the run dies here rather than attaching a buyer to
// the wrong organization.
try {
  // An httpRequest item that failed carries `error` as an OBJECT for a transport
  // failure ({message,name,stack,code}) and as the STRING 'aborted' when the
  // response is cut short. String(obj) is '[object Object]', which is how a
  // sender check silently stops working (lesson #142a). Normalise both.
  function errText(err) {
    if (err === undefined || err === null) { return null; }
    if (typeof err === 'string') { return err; }
    if (typeof err === 'object' && typeof err.message === 'string') { return err.message; }
    return 'unknown-transport-error';
  }

  var src = $('N09F Filter Fetchable Candidates').all();
  var items = $input.all();
  if (src.length !== items.length) {
    throw new Error('homepage-fetch-alignment-mismatch: ' + src.length + ' in, ' + items.length + ' out');
  }

  var config = $('N03 Validate Preflight').first().json.config;

  return items.map(function (item, i) {
    var j = item.json || {};
    var headers = j.headers || {};
    var err = errText(j.error);
    var byteLength = item.binary && item.binary.data && typeof item.binary.data.bytes === 'number'
      ? item.binary.data.bytes : null;
    var contentType = headers['content-type'] === undefined ? null : String(headers['content-type']);
    var status = j.statusCode === undefined ? null : j.statusCode;

    // These four guards live HERE, ahead of the decoder, so a non-HTML or
    // oversized body makes the PAGE unusable instead of killing the run.
    var fetchOk = err === null &&
      status === 200 &&
      contentType !== null && contentType.indexOf('text/html') === 0 &&
      byteLength !== null && byteLength <= config.gates.max_page_bytes;

    var reason = null;
    if (err !== null) { reason = 'transport-failure'; }
    else if (status !== 200) { reason = 'http-status-' + status; }
    else if (contentType === null || contentType.indexOf('text/html') !== 0) { reason = 'non-html-content-type'; }
    else if (byteLength === null) { reason = 'no-body'; }
    else if (byteLength > config.gates.max_page_bytes) { reason = 'body-too-large'; }

    return {
      json: {
        run_id: src[i].json.run_id,
        org_key: src[i].json.org_key,
        prospect_id: src[i].json.prospect_id,
        organization_name: src[i].json.organization_name,
        portfolio_units: src[i].json.portfolio_units,
        business_state: src[i].json.business_state,
        // The geography facts and any verdict already taken on them ride
        // through: N13 reads THIS node, not N09, so anything dropped here is
        // dropped for good -- and a conflict verdict lost here would reach the
        // model call it exists to prevent.
        // NOT `|| []`: an empty array is a real answer ("this organization has
        // no operating evidence") and, with a known out-of-scope state, the one
        // input that earns the decade block. A MISSING carry must stay missing
        // so geographyVerdict holds instead.
        operating_boros: src[i].json.operating_boros,
        decision: src[i].json.decision || null,
        reason_code: src[i].json.reason_code || null,
        geography_detail: src[i].json.geography_detail || null,
        from_roster: src[i].json.from_roster,
        candidate_host: src[i].json.candidate_host,
        candidate_index: src[i].json.candidate_index,
        fetch_ok: fetchOk,
        fetch_reason: reason,
        status: status,
        content_type: contentType,
        byte_length: byteLength,
        error: err
      },
      // Explicit: in runOnceForAllItems mode binary is never implicit, and the
      // bytes must survive to N12 (decode) and then N11 (hash).
      binary: item.binary
    };
  });
} catch (e) { throw new Error('N10B: ' + e.message); }

// N13 Select Verified Domain -- convergence and spine node.
//
// One incoming connection, from N09. It runs exactly once, AFTER the whole
// N09D/N09F subtree, including on a run where every candidate failed and N10C's
// true arm never executed at all. That ordering comes from CANVAS POSITION
// (D12), not from the connection array index.
try {
  // EVERY lookup whose key comes from outside this workflow goes through here.
  //
  // A bare object literal indexed with an external key resolves through
  // Object.prototype, so `constructor`, `toString`, `valueOf`, `hasOwnProperty`
  // and `__proto__` are truthy members of every table. That is not theoretical
  // here: the signal-type enum gate was `if (!HYPOTHESIS_TABLE[type])`, and it is
  // the ONLY enforcement of that enum -- the tool schema declares it but the model
  // API does not validate tool input -- so `signal_event_type: "__proto__"` was
  // ADMITTED, reached the review packet a person reads, and would have raised a
  // bare KeyError inside the authority's `RELATIONSHIPS[...]`, discarding all five
  // prospects after all five had been confirmed.
