  }

  // Returns [] for a node that never executed this run. Never let a skipped
  // branch look the same as a branch that ran and produced nothing useful:
  // callers that need that distinction check the upstream counts instead.
  function outputOf(nodeName) {
    try { return $(nodeName).all(); } catch (e) { return []; }
  }

  // The one string-comparison function, applied identically to BOTH sides of
  // every comparison. Case-PRESERVING: a buyer's name must match the page in case
  // as well as in characters.
  function normalize(s) {
    return String(s === undefined || s === null ? '' : s)
      .normalize('NFKC').replace(/\s+/g, ' ').trim();
  }

  var pre = $('N03 Validate Preflight').first().json;
  var run = pre.run;
  var config = pre.config;

  var all = outputOf('N10B Normalize Homepage Fetch');
  // Hash-last (D1): N11 is the tail of the homepage chain, so the decoded text
  // and the hash of the SAME bytes both arrive from there.
  var hashed = outputOf('N11 Hash Homepage Bytes');

  var frame = outputOf('N09 Build Candidate Frame');
  var summary = null;
  for (var f = 0; f < frame.length; f++) {
    if (frame[f].json._frame_summary) { summary = frame[f].json._frame_summary; break; }
  }

  var textByHost = {};
  for (var h = 0; h < hashed.length; h++) {
    var hj = hashed[h].json;
    textByHost[hj.candidate_host] = {
      page_text: hj.page_text, content_sha256: hj.content_sha256, byte_length: hj.byte_length
    };
  }

  var byOrg = {};
  for (var i = 0; i < all.length; i++) {
    var c = all[i].json;
    if (c._sentinel) { continue; }
    if (ownProp(byOrg, c.org_key) === undefined) { byOrg[c.org_key] = { org: c, candidates: [] }; }
    ownProp(byOrg, c.org_key).candidates.push(c);
  }

  var out = [];
  var keys = Object.keys(byOrg).sort();
  for (var k = 0; k < keys.length; k++) {
    var group = ownProp(byOrg, keys[k]);
    group.candidates.sort(function (a, b) { return a.candidate_index - b.candidate_index; });

    var chosen = null;
    for (var ci = 0; ci < group.candidates.length && !chosen; ci++) {
      var cand = group.candidates[ci];
      if (!cand.fetch_ok) { continue; }
      var decoded = textByHost[cand.candidate_host];
      if (!decoded || typeof decoded.page_text !== 'string') { continue; }

      // Section 4.4, both clauses. normalize() is applied identically to both
      // sides so the comparison is well defined in each direction.
      var haystack = normalize(decoded.page_text).toLowerCase();
      var needle = normalize(cand.organization_name).toLowerCase();
      var nameOnPage = needle.length > 0 && haystack.indexOf(needle) !== -1;

      // Section 4.4's second clause -- "the final URL host equals the requested
      // host" -- is NOT enforceable here and is not pretended to be. n8n's
      // httpRequest follows redirects and returns only the response headers
      // (content-type, content-length, date, connection); it exposes no final
      // URL, so a workflow cannot see where a redirect landed. An earlier
      // version of this node read a header that does not exist, which made the
      // check pass vacuously -- worse than not having it, because it read as
      // enforced. The residual gap is listed in FINDINGS.md under
      // "Still open, and deliberately not fixed here".
      //
      // What still holds: the organization's own name must appear on whatever
      // answered, and G3 additionally requires the single published mailbox to
      // be on this very host, so a redirect to an unrelated domain has to
      // publish a mailbox on the ORIGINAL domain to get through.
      if (nameOnPage) {
        chosen = { host: cand.candidate_host, content_sha256: decoded.content_sha256,
          byte_length: decoded.byte_length, candidate: cand };
      }
    }

    var org = group.org;
    if (chosen) {
      out.push({ json: {
        run_id: run.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
        organization_name: org.organization_name, portfolio_units: org.portfolio_units,
        business_state: org.business_state, from_roster: org.from_roster,
        operating_boros: org.operating_boros,
        domain_resolved: true, host: chosen.host,
        homepage_sha256: chosen.content_sha256, homepage_bytes: chosen.byte_length,
        // A geography decision taken in N09 is authoritative and survives here.
        // Overwriting it with null would send a conflict-held organization on to
        // the model call, which is the cost JT's policy says it must not incur.
        decision: org.decision || null, reason_code: org.reason_code || null,
        geography_detail: org.geography_detail || null, _sentinel: false
      } });
    } else {
      // Not an error and not a permanent rejection -- it records a tooling gap,
      // not a fact about the organization.
      out.push({ json: {
        run_id: run.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
        organization_name: org.organization_name, portfolio_units: org.portfolio_units,
        business_state: org.business_state, from_roster: org.from_roster,
        operating_boros: org.operating_boros,
        domain_resolved: false, host: null,
        homepage_sha256: null, homepage_bytes: null,
        // A geography decision already taken outranks this one: it is a fact
        // about the organization, where an unresolved domain is a tooling gap.
        decision: org.decision || 'HELD',
        reason_code: org.reason_code || 'domain-unresolved',
        geography_detail: org.geography_detail || null, _sentinel: false
      } });
    }
  }

  if (out.length === 0) { out.push({ json: { _sentinel: true, run_id: run.run_id } }); }
  out[0].json._frame_summary = summary;
  return out;
} catch (e) { throw new Error('N13: ' + e.message); }

// N15 Plan Page Fetches.
//
// N14 is strictly 1:1 with N13F, so identity is recovered by index alignment
// with a hard assertion, exactly as N10B does.
try {
  // The section 4.2 path list, ordered by PURPOSE PRIORITY rather than by the
  // order they are listed there. caps.max_pages_per_org is 8 and the list has 10
  // entries, so the order decides which two are dropped -- interleaving by purpose
  // guarantees all four purposes are attempted before any purpose gets a second
  // page. Without that, four buyer-identity paths could consume the cap and leave
  // contact-surface unfetched, which fails G3 for a reason that is not about the
  // organization at all.
  var PAGE_PLAN = [
    { path: '/about',                 purpose: 'organization-identity' },
    { path: '/contact',               purpose: 'contact-surface' },
    { path: '/leadership',            purpose: 'buyer-identity' },
    { path: '/news',                  purpose: 'signal' },
    { path: '/staff',                 purpose: 'buyer-identity' },
    { path: '/press',                 purpose: 'signal' },
    { path: '/team',                  purpose: 'buyer-identity' },
    { path: '/newsroom',              purpose: 'signal' },
    { path: '/our-story/leadership',  purpose: 'buyer-identity' },
    { path: '/careers',               purpose: 'signal' }
  ];

  // Deterministic, and unique per (org, path) by construction.
  function pageSlug(p) {
    return String(p).replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+/, '').replace(/-+$/, '').toLowerCase();
  }

  var orgs = $('N13F Filter Resolved Domains').all();
  var robots = $input.all();
  if (orgs.length !== robots.length) {
    throw new Error('robots-alignment-mismatch: ' + orgs.length + ' orgs, ' + robots.length + ' robots');
  }

  var config = $('N03 Validate Preflight').first().json.config;
  var UA_TOKEN = 'jtsomwaruconsulting-research';

  // A 404, a non-200 or a transport failure all mean "no restrictions
  // published" -- the absence of a robots.txt is not a prohibition.
  function disallowedPaths(body, status) {
    if (typeof body !== 'string' || body.length === 0) { return []; }
    if (status !== null && status !== undefined && status !== 200) { return []; }
    var rules = [];
    var active = false;
    var inAgentRun = false;
    var lines = body.split('\n');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].replace(/#.*$/, '').trim();
      if (!line) { continue; }
      var m = line.match(/^([A-Za-z-]+)\s*:\s*(.*)$/);
      if (!m) { continue; }
      var field = m[1].toLowerCase();
      var value = m[2].trim();
      if (field === 'user-agent') {
        var agent = value.toLowerCase();
        var matches = agent === '*' || agent.indexOf(UA_TOKEN) !== -1;
        // RFC 9309 section 2.2.1: CONSECUTIVE user-agent lines form ONE group.
        // Overwriting instead of accumulating made this fail OPEN: a robots.txt
        // reading "User-agent: *" / "User-agent: Googlebot" / "Disallow: /" --
        // a site that disallows everything for everyone -- had its rules thrown
        // away by the second agent line, and every path came back allowed. That
        // is 120 requests per run against real third-party hosts, with a UA that
        // names jtsomwaru.com, at a site that asked nobody to crawl it.
        active = inAgentRun ? (active || matches) : matches;
        inAgentRun = true;
        continue;
      }
      inAgentRun = false;
      if (field === 'disallow' && active && value) { rules.push(value); }
    }
    return rules;
  }

  var out = [];
  for (var o = 0; o < orgs.length; o++) {
    var org = orgs[o].json;
    var rj = robots[o].json || {};
    var rules = disallowedPaths(rj.data, rj.statusCode);

    var planned = 0;
    for (var p = 0; p < PAGE_PLAN.length; p++) {
      if (planned >= config.caps.max_pages_per_org) { break; }
      var entry = PAGE_PLAN[p];
      var blocked = null;
      for (var r = 0; r < rules.length; r++) {
        if (rules[r] === '/' || entry.path.indexOf(rules[r]) === 0) { blocked = rules[r]; break; }
      }
      if (blocked !== null) {
        out.push({ json: {
          run_id: org.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
          organization_name: org.organization_name, host: org.host,
          purpose: entry.purpose, path: entry.path, page_slug: pageSlug(entry.path),
          url: '', robots_allowed: false, reason_code: 'robots-disallowed', robots_rule: blocked
        } });
        continue;
      }
      planned++;
      out.push({ json: {
        run_id: org.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
        organization_name: org.organization_name, host: org.host,
        purpose: entry.purpose, path: entry.path, page_slug: pageSlug(entry.path),
        url: 'https://' + org.host + entry.path,
        robots_allowed: true, reason_code: null, robots_rule: null
      } });
    }
  }
  return out;
} catch (e) { throw new Error('N15: ' + e.message); }

