    if (err === undefined || err === null) { return null; }
    if (typeof err === 'string') { return err; }
    if (typeof err === 'object' && typeof err.message === 'string') { return err.message; }
    return 'unknown-transport-error';
  }

  var src = $('N15F Filter Planned Pages').all();
  var items = $input.all();
  if (src.length !== items.length) {
    throw new Error('page-fetch-alignment-mismatch: ' + src.length + ' in, ' + items.length + ' out');
  }

  var config = $('N03 Validate Preflight').first().json.config;

  return items.map(function (item, i) {
    var j = item.json || {};
    var headers = j.headers || {};
    var err = errText(j.error);
    var byteLength = item.binary && item.binary.data && typeof item.binary.data.bytes === 'number'
      ? item.binary.data.bytes : null;
    var contentType = headers['content-type'] === undefined ? null : String(headers['content-type']);
    var status = j.statusCode === undefined ? null : j.statusCode;

    var fetchOk = err === null &&
      status === 200 &&
      contentType !== null && contentType.indexOf('text/html') === 0 &&
      byteLength !== null && byteLength <= config.gates.max_page_bytes;

    var reason = null;
    if (err !== null) { reason = 'transport-failure'; }
    else if (status !== 200) { reason = 'http-status-' + status; }
    else if (contentType === null || contentType.indexOf('text/html') !== 0) { reason = 'non-html-content-type'; }
    else if (byteLength === null) { reason = 'no-body'; }
    else if (byteLength > config.gates.max_page_bytes) { reason = 'body-too-large'; }

    return {
      json: {
        run_id: src[i].json.run_id, org_key: src[i].json.org_key,
        prospect_id: src[i].json.prospect_id,
        organization_name: src[i].json.organization_name,
        host: src[i].json.host, purpose: src[i].json.purpose,
        path: src[i].json.path, page_slug: src[i].json.page_slug,
