      // over-long span fails _contract() before any per-field rule runs and
      // rejects all five prospects, after a person has confirmed all five.
      if (authorityWordCount(rawSpan) > config.gates.quote_span_max_words) {
        failure = 'span-too-many-words'; break;
      }
      if (rawSpan.length > QUOTE_SPAN_MAX_CHARS) { failure = 'span-too-long'; break; }
      // The span must be PRESENTABLE, not just admissible. The confirmation
      // artifact tells a person to find this text on the rendered page, and an
      // entity reference this lane cannot resolve -- a control-range `&#13;`, an
      // HTML5 name outside the table -- reaches them as source text no page
      // displays. Under decision A that artifact is the only attribution
      // control, so an instruction nobody can follow is worse than a hold: hold,
      // and let the next sweep quote a different span.
      //
      // Checked against the RAW span, which is what N30 renders. Checking the
      // normalized one would see references the normalizer MANUFACTURED (its
      // `&amp;` -> `&` turns source `&amp;#60;` into `&#60;`) and miss the fact
      // that the page prints those four characters literally.
      var badEntity = unresolvableEntity(rawSpan);
      if (badEntity !== null) { failure = 'quote-entity-unresolvable'; break; }
      rawSpans[name] = rawSpan;
      if (!valueInSpan(value, span)) { failure = 'value-not-in-span'; break; }
      if (valueTooLong(name, value)) { failure = 'value-too-long'; break; }
    }


    // G1 is evaluated against the FRAME's org_key and host. If the model is
    // allowed to return a different organization name -- a partner named in a
    // footer, a parent, a funder -- the bundle names an organization the burned
    // pool check was never run against, while the ledger records another. Both
    // sides go through normKey, so a legal suffix or punctuation difference is
    // not a mismatch; a different organization is.
    if (!failure && normKey(input.organization_name) !== org.org_key) {
      failure = 'organization-name-mismatch';
    }

    // _safe_identity_text() rejects any organization name, buyer name or buyer
    // title that is not a full match of IDENTITY_RE or contains a control
    // character. Nothing else in this workflow looked at those characters, so a
    // perfectly real value like 'Services for the UnderServed (S:US)' -- which
    // is in this lane's own seed roster -- produced a bundle that was rejected
    // after a human had already confirmed all five.
    if (!failure) {
      var identityFields = [
        ['organization.name', input.organization_name],
        ['buyer.name', input.buyer_name],
        ['buyer.title', input.buyer_title]
      ];
      for (var idf = 0; idf < identityFields.length && !failure; idf++) {
        if (!isSafeIdentityText(identityFields[idf][1])) {
          failure = 'identity-text-unsupported';
        }
      }
    }

    if (!failure) {
      var titleOk = false;
      var lowerTitle = String(input.buyer_title).toLowerCase();
      for (var t = 0; t < ROLE_ALLOWLIST.length && !titleOk; t++) {
        if (lowerTitle.indexOf(ROLE_ALLOWLIST[t]) !== -1) { titleOk = true; }
      }
      if (!titleOk) { failure = 'buyer-role-mismatch'; }
    }

    if (!failure) {
      if (!ownProp(HYPOTHESIS_TABLE, input.signal_event_type)) { failure = 'no-dated-signal'; }
      else if (!isIsoDate(input.signal_event_date)) { failure = 'no-dated-signal'; }
      else if (!dateAppearsOnPage(input.signal_event_date, input.signal_page_id)) {
        // Without this the date is simply asserted. `signal.event`'s value and
        // span are the same string, so the value-in-span check is a tautology
        // there, and the date -- which decides the staleness gate, the age in
        // the review packet and the whole "organization-specific trigger" claim
        // -- was never compared to the page at all. A model could move a real
        // headline forward to beat the age window and nothing would notice.
        failure = 'signal-date-not-on-page';
      }
      else {
        var age = daysBetween(run.as_of, input.signal_event_date);
        if (age === null) { failure = 'no-dated-signal'; }
        else if (age < 0) { failure = 'signal-date-implausible'; }
        else if (age > config.gates.max_signal_age_days) { failure = 'signal-stale'; }
      }
    }

    if (!failure) {
      var segSpan = input.segment_evidence_span;
      if (segSpan === null || segSpan === undefined || String(segSpan).trim() === '') {
        failure = 'segment-unclassified';
      } else if (!spanIsVerbatim(segSpan, input.organization_name_page_id)) {
        failure = 'span-not-verbatim';
      } else {
        // CLASSIFY here; ADMISSIBILITY is G0's decision at N26.
        //
        // Rejecting a property-management span as `segment-unclassified` here
        // made the whole documented PM path dead code: N26's
        // `segment-not-admissible` arm, its §6 row, and N30's
        // `held-property-management-<org_key>.json` artifact -- which exists to
        // record what would unblock the organization -- could never be reached,
        // because nothing ever arrived at N26 carrying that segment. A
        // classifier that refuses to name the class it was built to recognise
        // is the same defect as a priced reason code with no producer.
        //
        // Both outcomes are still HELD. This admits nothing new; it moves the
        // hold to the gate that can say why.
        var lowerSeg = String(segSpan).toLowerCase();
        var segHit = false;
        for (var sp = 0; sp < SEGMENT_PHRASES.length && !segHit; sp++) {
          if (lowerSeg.indexOf(SEGMENT_PHRASES[sp]) !== -1) { segHit = true; }
        }
        for (var pmp = 0; pmp < PM_PHRASES.length && !segHit; pmp++) {
          if (lowerSeg.indexOf(PM_PHRASES[pmp]) !== -1) { segHit = true; }
        }
        if (!segHit) { failure = 'segment-unclassified'; }
      }
    }

    if (failure) {
      var decision = (failure === 'signal-date-implausible') ? 'REJECT' : 'HELD';
      marker(org, decision, failure);
      continue;
    }

    var hyp = ownProp(HYPOTHESIS_TABLE, input.signal_event_type);
    var common = {
      run_id: run.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
      organization_name: org.organization_name, org: slimOrg(org),
      extracted: {
        organization_name: input.organization_name,
        buyer_name: input.buyer_name,
        buyer_title: input.buyer_title,
        signal_event_type: input.signal_event_type,
        signal_event_date: input.signal_event_date,
        signal_age_days: daysBetween(run.as_of, input.signal_event_date),
        segment_evidence_span: input.segment_evidence_span,
        hypothesis: hyp
      },
      decision: null, reason_code: null
    };

    function evidenceRow(field, value, span, pageId) {
      var page = ownProp(textByPageId, pageId);
      var row = JSON.parse(JSON.stringify(common));
      row.row_kind = 'field';
      row.field = field;
      row.value = String(value);
      // Committed: the raw substring, which is what admit matches.
      row.quote_span = ownProp(rawSpans, field) === undefined ? String(span) : ownProp(rawSpans, field);
      // Shown to a person: the normalized text they will actually see on the
      // page. A reviewer told to "find the quoted span" cannot find '</strong>'.
      row.readable_quote = String(span);
      // The page ACTUALLY cited, carried all the way to the committed record so
      // the URL a reviewer is told to open is the one the value came from.
      row.source_page_id = pageId;
      row.source_purpose = page ? page.purpose : null;
      row.source_url = page ? page.url : null;
      row.source_path = page ? page.snapshot_path : null;
      out.push({ json: row });
    }

    evidenceRow('organization.name', input.organization_name, input.organization_name_span, input.organization_name_page_id);
    evidenceRow('buyer.name', input.buyer_name, input.buyer_name_span, input.buyer_page_id);
    evidenceRow('buyer.title', input.buyer_title, input.buyer_title_span, input.buyer_page_id);
    // The COMMITTED VALUE for signal.event is not the headline. The authority's
    // _manifest_value() returns `event_type + "|" + event_date`, and admit hashes
    // that -- so hashing the quoted headline here produced a value_sha256 that
    // could never match, on every prospect, in every run. The quote_span stays
    // the headline; only the value differs from it.
    evidenceRow('signal.event',
      input.signal_event_type + '|' + input.signal_event_date,
      input.signal_span, input.signal_page_id);

    var inference = JSON.parse(JSON.stringify(common));
    inference.row_kind = 'inference';
    inference.field = 'hypothesis';
    inference.value = hyp.concept_id + '|' + hyp.question_concept_id;
    out.push({ json: inference });
  }

  // All hashing happens in N24. The JS Task Runner blocks require() and Web
  // Crypto's subtle.digest is asynchronous, so a Code node must not be asked to
  // produce a SHA-256.
  return out;
} catch (e) { throw new Error('N23: ' + e.message); }

// N25 Reassemble Prospects -- convergence and spine node.
try {
  // Returns [] for a node that never executed this run. Never let a skipped
  // branch look the same as a branch that ran and produced nothing useful:
  // callers that need that distinction check the upstream counts instead.
  function outputOf(nodeName) {
    try { return $(nodeName).all(); } catch (e) { return []; }
  }

  var run = $('N03 Validate Preflight').first().json.run;

  var rows = outputOf('N24 Hash Evidence Values');
  // The authoritative organization list. This is what guarantees that
  // skip_model and domain-unresolved organizations are still accounted for,
  // since they never produced an evidence row.
  var orgs = outputOf('N21 Assemble Extraction Requests')
    .filter(function (o) { return o.json._sentinel !== true; });

  var byProspect = {};
  for (var r = 0; r < rows.length; r++) {
    var row = rows[r].json;
    if (!byProspect[row.prospect_id]) { byProspect[row.prospect_id] = []; }
    byProspect[row.prospect_id].push(row);
  }

  var FIELD_ORDER = ['organization.name', 'buyer.name', 'buyer.title', 'signal.event'];

  var out = [];
  for (var o = 0; o < orgs.length; o++) {
    var org = orgs[o].json;
    var group = byProspect[org.prospect_id] || [];

    var markerRow = null;
    for (var g = 0; g < group.length; g++) {
      if (group[g].row_kind === 'marker') { markerRow = group[g]; break; }
    }

    if (markerRow) {
      out.push({ json: {
        run_id: run.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
        organization_name: org.organization_name, org: org,
        decision: markerRow.decision, reason_code: markerRow.reason_code,
        extracted: null, field_evidence: [], inference_evidence: [], _sentinel: false
      } });
      continue;
    }

    if (group.length === 0) {
      // Never reached the model at all: the reason was decided at N21.
      out.push({ json: {
        run_id: run.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
        organization_name: org.organization_name, org: org,
        decision: org.decision === null || org.decision === undefined ? 'HELD' : org.decision,
        reason_code: org.reason_code === null || org.reason_code === undefined
          ? 'model-output-unusable' : org.reason_code,
        extracted: null, field_evidence: [], inference_evidence: [], _sentinel: false
      } });
      continue;
    }

    var fieldRows = group.filter(function (x) { return x.row_kind === 'field'; });
    var inferenceRows = group.filter(function (x) { return x.row_kind === 'inference'; });

    var ordered = [];
    for (var f = 0; f < FIELD_ORDER.length; f++) {
      var match = null;
      for (var fr = 0; fr < fieldRows.length; fr++) {
        if (fieldRows[fr].field === FIELD_ORDER[f]) { match = fieldRows[fr]; break; }
      }
      if (!match) { throw new Error('evidence-row-missing: ' + org.prospect_id + ' ' + FIELD_ORDER[f]); }
      // readable_quote is NOT optional here. quote_span is the raw substring,
      // markup included, because that is what admit matches. readable_quote is
      // the only thing a person can actually find on the rendered page, and the
      // attribution confirmation (7.5b) is the sole attribution control.
      // Omitting it from this whitelist dropped it silently and the packet went
      // back to showing '</strong>' through the middle of a name.
      if (typeof match.readable_quote !== 'string' || match.readable_quote === '') {
        throw new Error('readable-quote-missing: ' + org.prospect_id + ' ' + FIELD_ORDER[f]);
      }
      ordered.push({
        field: match.field, value: match.value, quote_span: match.quote_span,
        readable_quote: match.readable_quote,
        value_sha256: match.value_sha256, source_page_id: match.source_page_id,
        source_purpose: match.source_purpose, source_url: match.source_url,
        source_path: match.source_path, confidence: 'confident'
      });
    }
    if (inferenceRows.length !== 1) {
      throw new Error('inference-row-count: ' + org.prospect_id + ' has ' + inferenceRows.length);
    }

    out.push({ json: {
      run_id: run.run_id, org_key: org.org_key, prospect_id: org.prospect_id,
      organization_name: org.organization_name, org: org,
      decision: null, reason_code: null,
      extracted: fieldRows[0].extracted,
      field_evidence: ordered,
      inference_evidence: [{
        value: inferenceRows[0].value, value_sha256: inferenceRows[0].value_sha256
      }],
      _sentinel: false
    } });
  }

  // The standing regression guard against a reintroduced fan-in: under the r1
  // wiring this fired on the very first mixed run.
  if (out.length !== orgs.length) {
    throw new Error('prospect-reassembly-count-mismatch: ' + out.length + ' out, ' + orgs.length + ' in');
  }

  if (out.length === 0) { out.push({ json: { _sentinel: true, run_id: run.run_id } }); }
  return out;
} catch (e) { throw new Error('N25: ' + e.message); }

// N26 Apply Gates. Per item. G0..G5 in the section 5 order.
try {
  // Strips legal suffixes and articles only. Domain nouns are never stripped --
  // removing `housing` or `services` would collide distinct organizations.
