      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/&/g, ' and ')
      .replace(/[^a-z0-9]+/g, ' ')
      .trim()
      .split(' ')
      .filter(function (t) { return t && DROP.indexOf(t) === -1; })
      .join('-');
  }

  // A single shared token from COMMON_TOKENS is NOT a near match -- this is the
  // `living` / `health` regex-artifact class JT cleared on 2026-09-09.
  var COMMON_TOKENS = ['housing', 'community', 'services', 'service', 'health', 'living',
    'group', 'center', 'centre', 'association', 'management', 'properties', 'property',
    'realty', 'urban', 'new', 'york', 'nyc', 'city', 'jersey', 'american', 'national',
    'family', 'families', 'home', 'homes', 'care'];

  var ROLE_ALLOWLIST = ['property management', 'property and asset', 'asset management',
    'portfolio operations', 'housing operations', 'director of housing', 'facilities',
    'compliance', 'operations'];

  var SEGMENT_PHRASES = ['permanent supportive housing', 'supportive housing',
    'transitional housing', 'homeless services', 'sro', 'congregate care'];

  var PM_PHRASES = ['property management', 'residential management', 'asset management'];

  var TIER_B_PLUS = ['compliance', 'qicompliance', 'operations', 'propertymanagement',
    'propertymgmt', 'assetmanagement', 'housingoperations', 'facilities'];

  // Tier C is a REJECTION, not a low rank: an operations message landing in a
  // recruiting inbox reads as a vendor mismatch and is discarded before it reaches
  // anyone who owns the problem.
  var TIER_C = ['recruiting', 'recruitingmanagers', 'careers', 'jobs', 'hr',
    'humanresources', 'development', 'communications', 'press', 'media', 'donate',
    'giving', 'volunteer'];

  var OPENERS = ['dated-observation', 'condition-first', 'direct-question-context',
    'operational-contrast'];
  var CLOSINGS = ['open-process', 'timing', 'standardization', 'routing'];

  function utcDate(iso) { return String(iso === undefined || iso === null ? '' : iso).slice(0, 10); }

  function daysBetween(fromIso, toIso) {
    var a = Date.parse(String(fromIso).slice(0, 10) + 'T00:00:00Z');
    var b = Date.parse(String(toIso).slice(0, 10) + 'T00:00:00Z');
    if (isNaN(a) || isNaN(b)) { return null; }
    return Math.floor((a - b) / 86400000);
  }

  function addDays(iso, days) {
    var t = Date.parse(String(iso).slice(0, 10) + 'T00:00:00Z');
    if (isNaN(t)) { throw new Error('addDays: unparseable date'); }
    return new Date(t + days * 86400000).toISOString().slice(0, 10);
  }

  function isIsoDate(s) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) { return false; }
    var t = Date.parse(String(s) + 'T00:00:00Z');
