  // not a jurisdiction is an ABSENT fact: held for 7 days and re-asked next run,
  // never rejected for ten years. Padding and case are normalized rather than
  // rejected, because `NY ` is New York and holding it would be its own error.
  //
  // The set is the USPS jurisdictions: 50 states, DC, the five territories, and
  // the three overseas military codes. A non-US subdivision (`ON`, `BC`) is
  // therefore an absent fact rather than a verified out-of-scope one -- the
  // conservative direction, and the cost is a repeated hold rather than a wrong
  // ten-year block.
  var US_JURISDICTIONS = ['AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA',
    'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD', 'MA', 'MI', 'MN',
    'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ', 'NM', 'NY', 'NC', 'ND', 'OH', 'OK',
    'OR', 'PA', 'RI', 'SC', 'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI',
    'WY', 'DC', 'AS', 'GU', 'MP', 'PR', 'VI', 'AA', 'AE', 'AP'];

  function stateOf(raw) {
    // Non-strings are absent, not coerced. `String(['CA'])` is 'CA', so an
    // array-valued field would manufacture a VERIFIED out-of-scope verdict and a
    // ten-year block out of a shape nobody intended. SODA returns only strings
    // and nulls today; this costs one line and removes the question.
    if (typeof raw !== 'string') { return ''; }
    var s = raw.trim().toUpperCase();
    return US_JURISDICTIONS.indexOf(s) === -1 ? '' : s;
  }

  // The ONE place that decides whether a value is a real NYC borough.
  //
  // The sibling of `stateOf`, and it exists because the geography gate has TWO
  // inputs and only one of them was ever given a membership test. `boro` was read
  // as `String(row.boro).trim().toUpperCase()` and kept if non-empty, so any value
  // HPD returned that was not a borough name -- a numeric code, a shifted column,
  // a renamed field -- entered `operating_boros` as a borough that matches none of
  // the five. The verdict then read that as "operates nowhere in NYC", which with
  // a known out-of-scope mailing state is the one input that earns 3650 days.
  //
  // The live feed holds exactly the five names today and no NULL over 203,887 rows
  // (`test/fixtures/soda/boro-vocabulary.json`), so this is the class rather than
  // a live instance -- which is precisely what `businessstate` was until HPD added
  // `NA`, then `OFFICE`, then `NU`. Closing it on the same terms costs nothing.
  //
  // Anything not a borough is an ABSENT fact, never a present one that happens to
  // be out of scope. Padding and case are normalized rather than rejected.
  var NYC_BOROUGHS = ['MANHATTAN', 'BRONX', 'BROOKLYN', 'QUEENS', 'STATEN ISLAND'];

