    if (typeof raw !== 'string') { return ''; }
    var up = raw.trim().toUpperCase();
    return NYC_BOROUGHS.indexOf(up) === -1 ? '' : up;
  }

  // The scope question has FOUR answers, and conflating any two of them has cost
  // this lane a defect each time.
  //
  //   in scope            operating boroughs in NYC, or a NY/NJ state -> proceed
  //   no answer           neither -> HELD `geography-unknown`, 7 days
  //   conflict            verified in-scope OPERATING geography, but the MAILING
  //                       state is a real jurisdiction outside NY/NJ -> HELD
  //                       `geography-conflict-review`, 90 days, for a person
  //   confirmed out       a real jurisdiction outside NY/NJ and no in-scope
  //                       operating evidence -> REJECT, 3650 days
  //
  // The conflict arm exists because `businessstate` is where the registrant
  // receives POST, not where it operates: an organization running buildings in
  // the Bronx can register a New Jersey or Delaware mailing address, and treating
  // that as "out of scope" blocked it for a decade on the strength of an envelope.
  // JT's policy of 2026-09-17 reserves the ten-year block for confirmed
  // operating/business geography outside scope, and this is where that is decided.
  //
  // `operatingEvidenceCount` is what separates "no boroughs" from "no readable
  // boroughs", and the distinction decides between 7 days and 3650. See below.
  //
  // Called in TWO places on purpose: N09, before anything is fetched or paid for,
  // so a conflict costs no model call; and G0, which is the node that persists the
  // verdict and must be right on its own input.
  function geographyVerdict(operatingBoros, rawState, operatingEvidenceCount) {
