    // old behaviour -- every framed candidate silently repriced as a roster entry
    // -- which is the same "a node forgot to carry it" failure the array check
    // below exists for, and it fails in the burn direction. Loud instead.
    if (typeof operatingEvidenceCount !== 'number' ||
        !isFinite(operatingEvidenceCount) || operatingEvidenceCount < 0) {
      throw new Error('operating-evidence-count-not-supplied: ' +
        (operatingEvidenceCount === undefined ? 'undefined' : String(operatingEvidenceCount)));
    }
    // An ARRAY is a real answer about operating evidence. Anything else means the
    // fact was never supplied: a node forgot to carry it, or carried the wrong
    // shape. That is a defect in the pipeline, not evidence about the
    // organization, and it must not fall through to "no operating evidence" --
    // which is precisely how a missing carry became a ten-year block once already.
    // Same convention as stateOf and boroOf above: an unusable value is an ABSENT
    // fact, never a present one that happens to be out of scope.
    if (!Array.isArray(operatingBoros)) {
      return { decision: 'HELD', reason_code: 'geography-unknown',
        detail: 'operating geography not supplied (' +
          (operatingBoros === undefined ? 'undefined' : typeof operatingBoros) + ')' };
    }
