      else { unreadable.push(String(operatingBoros[b])); }
    }
    var operatingInScope = boros.length > 0;
    var state = stateOf(rawState);
    var stateKnown = state !== '';
    var stateInScope = state === 'NY' || state === 'NJ';
    var detail = 'boros=' + (boros.join('/') || '(none)') + ' state=' + (state || '(none)');

    if (operatingInScope && stateKnown && !stateInScope) {
      return { decision: 'HELD', reason_code: 'geography-conflict-review',
        detail: detail + ' -- operates in NYC, mails to ' + state };
    }
    if (operatingInScope || stateInScope) {
      return { decision: null, reason_code: null, detail: detail };
    }
    // Nothing in scope. Before this can be read as CONFIRMED out of scope, the
    // empty borough set has to mean "none" rather than "none we could read".
    //
    // A candidate with operating evidence -- HPD registrations -- exists only
    // because it holds buildings in `tesw-yqqr`, which is the NYC building
    // registration file: its operating geography is in scope as a matter of
    // record, whatever the borough column happened to say. An empty or unreadable
    // borough set on such a candidate is a fact we failed to READ, so it is held
    // and re-asked, never burned for a decade.
    //
    // A roster entry carries no registrations, and its boroughs are what the
    // curator verified and recorded. There `[]` genuinely means none, and with a
    // known out-of-scope state that is the confirmed reading the block is for.
    if (unreadable.length) {
      return { decision: 'HELD', reason_code: 'geography-unknown',
        detail: detail + ' -- unreadable borough value(s): ' + unreadable.join('/') };
    }
    if (operatingEvidenceCount > 0) {
      return { decision: 'HELD', reason_code: 'geography-unknown',
        detail: detail + ' -- ' + operatingEvidenceCount +
          ' HPD registration(s) but no readable borough' };
    }
    if (!stateKnown) {
      return { decision: 'HELD', reason_code: 'geography-unknown', detail: detail };
    }
    return { decision: 'REJECT', reason_code: 'out-of-scope-geography', detail: detail };
  }

  var item = $input.item;
  if (item.json._sentinel === true) { return item; }

  // Per-item mode does not carry the preflight item, so run-level context is
  // read by explicit upstream reference (lesson #25/#50).
  var idx = $('N06 Build Exclusion Index').first().json;
  var run = idx.run;
  var config = idx.config;

  var j = item.json;
  var org = j.org || {};
  var ex = j.extracted;

  var gates = {};
  var decision = 'ADVANCE';
  var reasonCode = null;
  var channelTier = null;
  var channelRank = null;
  var channelAddress = null;

  function settle(gate, pass, detail, verdict, reason) {
    gates[gate] = { pass: pass, detail: detail };
    if (!pass && decision === 'ADVANCE') { decision = verdict; reasonCode = reason; }
  }

