  // clamp rejection) is authoritative: the gates below describe what could not
  // be evaluated rather than inventing a second verdict.
  if (j.decision === 'HELD' || j.decision === 'REJECT') {
    return { json: Object.assign({}, j, {
      decision: j.decision, reason_code: j.reason_code, channel_tier: null,
      rank_key: null, gate_report: { decided_upstream: true, reason_code: j.reason_code }
    }) };
  }

  // --- G0 scope ----------------------------------------------------------
  // Four answers, from the one shared function N09 already applied before
  // anything was fetched or paid for: in scope; no answer at all (HELD, 7d); a
  // verified in-scope OPERATING geography contradicted by an out-of-scope
  // MAILING state (HELD, 90d, for a person); or a confirmed out-of-scope
  // geography (REJECT, 3650d). Recomputed here rather than trusted, because
  // this is the node that PERSISTS the verdict and it has to be right on its
  // own input.
  //
  // `operating_boros` is the boroughs of the organization's own HPD
  // registrations, merged with the roster's verified ones. It replaces the
  // former single `org.boro`, which nothing ever populated -- the borough arm
  // of this gate was dead code, so until now the question was decided entirely
  // by a mailing address.
  // `portfolio_units` is the HPD operating evidence this organization is known to
  // hold -- buildings on the frame page, or the roster's recorded registration
  // matches, whichever is larger -- carried from N09 through N10B/N13/N21. It
  // decides whether an empty borough set means "operates nowhere in NYC" (no
  // registrations anywhere: 0) or "holds NYC buildings but the borough column
  // was unreadable" (> 0). Not defaulted here -- a dropped carry throws in
  // geographyVerdict rather than being silently repriced and burned for a decade.
  var geo = geographyVerdict(org.operating_boros, org.business_state, org.portfolio_units);
  if (geo.decision) {
    settle('G0_scope', false, geo.detail, geo.decision, geo.reason_code);
  } else {
    var segSpan = String(ex && ex.segment_evidence_span ? ex.segment_evidence_span : '').toLowerCase();
    var segment = null;
    for (var s = 0; s < SEGMENT_PHRASES.length && !segment; s++) {
      if (segSpan.indexOf(SEGMENT_PHRASES[s]) !== -1) { segment = 'supportive-housing'; }
    }
    if (!segment) {
      for (var pm = 0; pm < PM_PHRASES.length && !segment; pm++) {
        if (segSpan.indexOf(PM_PHRASES[pm]) !== -1) { segment = 'property-management'; }
      }
    }
    if (segment === 'supportive-housing') {
      settle('G0_scope', true, geo.detail + '; segment=supportive-housing', null, null);
    } else if (segment === 'property-management') {
      // Researched and held, never emitted: the contract pins segment to
      // supportive-housing, so a property-management prospect cannot be
      // expressed in the record jt-ops admit validates.
      settle('G0_scope', false, 'segment=property-management', 'HELD', 'segment-not-admissible');
    } else {
      settle('G0_scope', false, 'segment unclassified', 'REJECT', 'segment-unclassified');
    }
  }

  // --- G1 not burned ------------------------------------------------------
  var exact = {};
  for (var e = 0; e < idx.exclusion.exact.length; e++) { exact[idx.exclusion.exact[e]] = true; }
  var host = String(org.host === undefined || org.host === null ? '' : org.host).toLowerCase();
  var burned = exact[j.org_key] === true || (host !== '' && exact[host] === true);
  settle('G1_not_burned', !burned,
    burned ? 'org_key or domain matches the exclusion union' :
      'clear vs ' + idx.exclusion_health.universe_records_usable + ' universe keys, ' +
      idx.exclusion_health.ledger_entries_usable + ' ledger, ' +
      idx.exclusion_health.carryover_usable + ' carryover, ' +
      idx.exclusion_health.protected_names_usable + ' protected',
    'REJECT', 'burned-pool-duplicate');

  // --- G2 named buyer -----------------------------------------------------
  var title = ex ? String(ex.buyer_title || '') : '';
  var titleHit = null;
  for (var t = 0; t < ROLE_ALLOWLIST.length && !titleHit; t++) {
    if (title.toLowerCase().indexOf(ROLE_ALLOWLIST[t]) !== -1) { titleHit = ROLE_ALLOWLIST[t]; }
  }
  var buyerName = ex ? String(ex.buyer_name || '') : '';
  settle('G2_named_buyer', buyerName !== '' && titleHit !== null,
    titleHit ? "title matched ROLE_ALLOWLIST token '" + titleHit + "'; span verbatim-verified"
             : 'no allowlisted title',
    'HELD', buyerName === '' ? 'no-named-buyer' : 'buyer-role-mismatch');

  // --- G3 reachable channel ----------------------------------------------
  // A faithful pre-image of the jt-ops verified-channel owner. If this is looser
  // than that owner, jt-ops gate rejects a prospect this workflow advanced and
  // the cohort of five breaks.
  // The www. alias of the same registrable host counts as the same host.
  function mailboxIsOnVerifiedHost(addr, host) {
    if (typeof addr !== 'string' || typeof host !== 'string' || host === '') { return false; }
    var at = addr.lastIndexOf('@');
    if (at === -1) { return false; }
    var domain = addr.slice(at + 1).toLowerCase();
    var want = host.toLowerCase().replace(/^www\./, '');
    return domain === want || domain === 'www.' + want ||
      domain.slice(-(want.length + 1)) === '.' + want;
  }

  var contactPage = null;
  var pages = Array.isArray(org.pages) ? org.pages : [];
  for (var p = 0; p < pages.length; p++) {
    if (pages[p].purpose === 'contact-surface') { contactPage = pages[p]; break; }
  }
  if (!contactPage) {
    settle('G3_channel', false, 'no contact-surface page', 'HELD', 'no-published-email');
  } else if (typeof contactPage.byte_length === 'number' &&
