    // G3 is a faithful pre-image of the jt-ops verified-channel owner, and that
    // owner reads the contact surface with a 512 KiB ceiling. Looser here means
    // a prospect this workflow advanced is rejected there, and the cohort of
    // five breaks on an organization that never had a chance.
    settle('G3_channel', false, 'contact page exceeds the owner ceiling',
      'HELD', 'contact-page-too-large');
  } else {
    var addrs = Array.isArray(contactPage.mailto_recipients) ? contactPage.mailto_recipients : [];
    var https = String(contactPage.url || '').indexOf('https://') === 0;
    if (!https) {
      settle('G3_channel', false, 'contact page is not https', 'HELD', 'no-published-email');
    } else if (addrs.length === 0) {
      settle('G3_channel', false, 'zero published addresses', 'HELD', 'no-published-email');
    } else if (addrs.length > 1) {
      // Both fail closed. Never construct an address from a domain pattern.
      settle('G3_channel', false, addrs.length + ' distinct mailboxes', 'HELD', 'ambiguous-mailbox');
    } else if (!mailboxIsOnVerifiedHost(addrs[0], org.host)) {
      // n8n cannot see where a redirect landed -- it follows redirects and
      // exposes no final URL -- so this is what stands
      // between a hijacked or parked candidate host and an "advanced" prospect:
      // a squatter would have to publish a mailbox on the ORIGINAL domain.
      // It also enforces the plainer thing -- the mailbox must belong to the
      // organization whose page published it.
      settle('G3_channel', false, 'published mailbox is not on the verified host',
        'HELD', 'ambiguous-mailbox');
    } else {
      channelAddress = addrs[0];
      var local = String(channelAddress).split('@')[0].toLowerCase().replace(/[^a-z0-9]/g, '');
      var surname = buyerName.split(/\s+/).filter(Boolean).pop();
      surname = surname ? surname.toLowerCase().replace(/[^a-z0-9]/g, '') : '';
      var first = buyerName.split(/\s+/).filter(Boolean)[0];
      first = first ? first.toLowerCase().replace(/[^a-z0-9]/g, '') : '';

      if (TIER_C.indexOf(local) !== -1) {
        // A rejection, not a low rank: cohort one established that an operations
        // message in a recruiting inbox is discarded before it reaches anyone
        // who owns the problem.
        channelTier = 'C';
        settle('G3_channel', false, "local-part '" + local + "' routes to tier C",
          'REJECT', 'channel-routing-mismatch');
      } else if (surname && (local.indexOf(surname) !== -1 ||
                 local === (first ? first.charAt(0) : '') + surname ||
                 local === first + surname)) {
        channelTier = 'A'; channelRank = 0;
        settle('G3_channel', true, "tier=A; local-part '" + local + "'", null, null);
      } else if (TIER_B_PLUS.indexOf(local) !== -1) {
        channelTier = 'B+'; channelRank = 1;
        settle('G3_channel', true, "tier=B+; local-part '" + local + "'", null, null);
      } else {
        channelTier = 'B'; channelRank = 2;
        settle('G3_channel', true, "tier=B; local-part '" + local + "'", null, null);
      }
