  var card = idx.proof_card;
  gates.G4_proof_asset = { pass: true, detail: 'card ' + card.card_id + ' verified_by=jt at ' + card.verified_at };

  // --- G5 organization-specific trigger ----------------------------------
  if (!ex || !ex.signal_event_type) {
    settle('G5_trigger', false, 'no dated signal', 'HELD', 'no-dated-signal');
  } else {
    var age = ex.signal_age_days;
    if (age === null || age === undefined) {
      settle('G5_trigger', false, 'signal date unparseable', 'HELD', 'no-dated-signal');
    } else if (age < 0) {
      settle('G5_trigger', false, 'future-dated signal', 'REJECT', 'signal-date-implausible');
    } else if (age > config.gates.max_signal_age_days) {
      settle('G5_trigger', false, 'signal age ' + age + 'd', 'HELD', 'signal-stale');
    } else {
      settle('G5_trigger', true, ex.signal_event_type + ' ' + ex.signal_event_date + ', age ' + age + 'd', null, null);
    }
