  var rankKey = [
    channelRank === null ? 99 : channelRank,
    signalAge,
    -(typeof org.portfolio_units === 'number' ? org.portfolio_units : 0),
    j.org_key
  ];

  return { json: Object.assign({}, j, {
    decision: decision,
    reason_code: reasonCode,
    channel_tier: channelTier,
    channel_address: channelAddress,
    rank_key: rankKey,
    gate_report: {
      schema_version: 'c2-discovery-gate-report-v1',
      prospect_id: j.prospect_id, run_id: run.run_id,
      evaluated_at: new Date().toISOString().replace(/\.\d+Z$/, 'Z'),
      decision: decision, reason_code: reasonCode,
      gates: gates, channel_tier: channelTier, rank_key: rankKey
    }
  }) };
} catch (e) { throw new Error('N26: ' + e.message); }

// N28 Rank & Select Five -- convergence and spine node.
try {
