  // happened to forward. N27 exists so the boundary is legible in the canvas.
  var all = outputOf('N26 Apply Gates').filter(function (x) { return x.json._sentinel !== true; });

  var advance = [];
  var held = [];
  var rejected = [];
  for (var i = 0; i < all.length; i++) {
    var j = all[i].json;
    if (j.decision === 'ADVANCE') { advance.push(j); }
    else if (j.decision === 'REJECT') { rejected.push(j); }
    else { held.push(j); }
  }

