      opener_style: OPENERS[s % 4],
      closing_form: CLOSINGS[(s + Math.floor(s / 4)) % 4],
      proof_placement: proofLicensed ? ['middle', 'after-question-context'][s % 2] : 'omit-if-unlicensed'
    };
  }
