  // it is written back rather than left off the artifact a human reviews.
  for (var gr = 0; gr < selected.length; gr++) {
    if (!selected[gr].gate_report || !selected[gr].gate_report.gates) { continue; }
    selected[gr].gate_report.gates.G6_structure = {
      pass: true,
      detail: 'rank index ' + gr + ' -> ' + selected[gr].structure.opener_style + ' / ' +
        selected[gr].structure.proof_placement + ' / ' + selected[gr].structure.closing_form
    };
  }

