  // drafts, so a three-prospect bundle is not a partial win -- it is unusable.
  return [{ json: {
    run: run, config: config,
    cohort_complete: selected.length === N,
    required_cohort_size: N,
    selected: selected, surplus: surplus, held: held, rejected: rejected,
    near_matches: summary ? summary.near_matches : [],
    frame_summary: summary,
    exclusion_health: idx.exclusion_health,
    proof_card: pre.proof_card,
    records_processed: all.length
