    'segment-unclassified':       { outcome: 'held', days: 180 },
    'segment-not-admissible':     { outcome: 'held', days: 180 },
    'no-published-email':         { outcome: 'held', days: 90 },
    'ambiguous-mailbox':          { outcome: 'held', days: 90 },
    'domain-unresolved':          { outcome: 'domain-unresolved', days: 90 },
