    'no-dated-signal':            { outcome: 'held', days: 45 },
    'signal-stale':               { outcome: 'held', days: 45 },
    'buyer-role-mismatch':        { outcome: 'held', days: 60 },
    'quote-not-raw-verbatim':     { outcome: 'held', days: 7 },
    'span-too-many-words':        { outcome: 'held', days: 7 },
    'span-too-long':              { outcome: 'held', days: 7 },
    'quote-entity-unresolvable':  { outcome: 'held', days: 7 },
    'identity-text-unsupported':  { outcome: 'held', days: 180 },
    'contact-page-too-large':     { outcome: 'held', days: 90 },
    'organization-name-mismatch': { outcome: 'held', days: 180 },
    'source-purpose-mismatch':    { outcome: 'held', days: 7 },
    'signal-date-not-on-page':    { outcome: 'held', days: 45 },
    'value-too-long':             { outcome: 'held', days: 7 },
    'span-not-verbatim':          { outcome: 'held', days: 7 },
    'value-not-in-span':          { outcome: 'held', days: 7 },
    'model-output-unusable':      { outcome: 'held', days: 7 },
    'model-call-failed':          { outcome: 'held', days: 7 },
