  // Scanned in one pass rather than by chained regex replaces, because a chain
  // loses the offsets. Block-level closes (and a few opens) become newlines; every
  // other tag becomes a space; inline tags deliberately do not break, or a table
  // row could never show a name beside a title.
  //
  // DELIBERATE DIFFERENCES from the regex chain this replaced, each verified by
  // running both side by side:
  //   * `<br>` still breaks a line. It is not a block element, but it is the
  //     separator on a large share of staff pages, and without it a span can be
  //     stitched across two PEOPLE -- exactly what the line unit exists to stop.
  //   * `&AMP;` / `&LT;` and the rest now decode case-insensitively, as `&NBSP;`
  //     already did. HTML entity names are case-insensitive to a browser, so the
  //     old behaviour showed the model text no reader would see.
  //   * An UNTERMINATED `<script>` or `<style>` now swallows the rest of the
  //     document instead of emitting its source as page text. Fail-closed: script
  //     source is not prose, and admitting it lets a model quote a JS string
  //     literal as a person's title.
  //   * A `<` with no closing `>` is dropped rather than kept as literal text.
  var BLOCK_CLOSE_RE = /^<\/(p|div|li|tr|h[1-6]|dt|dd|section|article|header|footer|nav|aside|blockquote|figcaption|caption|ul|ol|dl|table|tbody|thead|tfoot|form|fieldset|address|pre|main)>/i;
  var BLOCK_OPEN_RE = /^<(hr|br|tr|li|p|div)\b[^>]*\/?>/i;
  var ENTITIES = { '&nbsp;': ' ', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&apos;': "'", '&amp;': '&' };
  // Unicode whitespace, not just the ASCII five. A UTF-8 BOM, a literal U+00A0
  // between a name and a title, and U+3000 in CJK copy are all ordinary on real
  // pages, and an ASCII-only set left them in the normalized text. That is not
  // cosmetic: `&nbsp;` already decodes to a plain space here, so the model sees
  // one span for the entity spelling and a different one for the literal byte,
  // and a span returned with an ASCII space passes spanIsVerbatim (which NFKC-
  // folds) but fails the raw-span derivation, holding the prospect for
  // quote-not-raw-verbatim. `\n` is excluded because it is this scanner's own
  // line marker, not page whitespace.
  var WS_RE = /\s/;
  function isSpace(ch) { return ch !== '\n' && WS_RE.test(ch); }

  // LINEAR IN THE PAGE LENGTH, and it has to be. An earlier version rebuilt the
  // accumulated offset array with `concat` once per line, which is O(lines x
  // bytes): 256 KiB took 1.9 s and a page at the configured 2 MiB ceiling did not
  // finish in two minutes. N19 runs this on every fetched page -- up to ~120 a run
  // -- and N23 re-runs it per field. Everything below appends; nothing copies.
  // Exactly the names HTML5 gives an uppercase form: AMP, LT, GT, QUOT, COPY,
  // REG. `&APOS;`, `&NBSP;` and `&TRADE;` are NOT among them -- a browser prints
  // those literally -- so they sit in the case-sensitive table with the rest.
  var LEGACY_CI = { amp: '&', lt: '<', gt: '>', quot: '"',
    copy: '©', reg: '®' };

