  // above. A blanket toLowerCase() turned `&Aacute;ngel` into `ángel` -- a silently
  // wrong rendering of a real person's name, in the one string a reviewer is told
  // to match against the page.
  var DISPLAY_ENTITIES = {
    mdash: '—', ndash: '–', hellip: '…', rsquo: '’',
    lsquo: '‘', ldquo: '“', rdquo: '”', bull: '•',
    middot: '·', deg: '°', sect: '§', para: '¶',
    dagger: '†', Dagger: '‡', prime: '′', Prime: '″',
    minus: '−', times: '×', divide: '÷', plusmn: '±',
    euro: '€', pound: '£', yen: '¥', cent: '¢',
    frac12: '½', frac14: '¼', frac34: '¾', sup1: '¹',
    sup2: '²', sup3: '³', ordm: 'º', ordf: 'ª',
    micro: 'µ', permil: '‰', laquo: '«', raquo: '»',
    lsaquo: '‹', rsaquo: '›', sbquo: '‚', bdquo: '„',
    iquest: '¿', iexcl: '¡', rarr: '→', larr: '←',
    harr: '↔', uarr: '↑', darr: '↓',
    apos: "'", nbsp: ' ', trade: '™',
    star: '☆', starf: '★', bigstar: '★',
    check: '✓', ensp: ' ', emsp: ' ', thinsp: ' ', shy: '',
    aacute: 'á', Aacute: 'Á', eacute: 'é', Eacute: 'É',
    iacute: 'í', Iacute: 'Í', oacute: 'ó', Oacute: 'Ó',
    uacute: 'ú', Uacute: 'Ú', agrave: 'à', Agrave: 'À',
    egrave: 'è', Egrave: 'È', igrave: 'ì', Igrave: 'Ì',
    ograve: 'ò', Ograve: 'Ò', ugrave: 'ù', Ugrave: 'Ù',
    acirc: 'â', Acirc: 'Â', ecirc: 'ê', Ecirc: 'Ê',
    icirc: 'î', Icirc: 'Î', ocirc: 'ô', Ocirc: 'Ô',
    ucirc: 'û', Ucirc: 'Û', auml: 'ä', Auml: 'Ä',
    euml: 'ë', Euml: 'Ë', iuml: 'ï', Iuml: 'Ï',
    ouml: 'ö', Ouml: 'Ö', uuml: 'ü', Uuml: 'Ü',
    yuml: 'ÿ', Yuml: 'Ÿ', atilde: 'ã', Atilde: 'Ã',
    ntilde: 'ñ', Ntilde: 'Ñ', otilde: 'õ', Otilde: 'Õ',
    ccedil: 'ç', Ccedil: 'Ç', aring: 'å', Aring: 'Å',
    oslash: 'ø', Oslash: 'Ø', aelig: 'æ', AElig: 'Æ',
    szlig: 'ß', ETH: 'Ð', eth: 'ð', THORN: 'Þ',
    thorn: 'þ', oelig: 'œ', OElig: 'Œ', scaron: 'š',
    Scaron: 'Š', zcaron: 'ž', Zcaron: 'Ž', ccaron: 'č',
    uring: 'ů'
