  // hasOwnProperty, not `[body]`. A bare object literal indexed with a
  // page-controlled key resolves through Object.prototype, so `&constructor;`
  // rendered as "function Object() { [native code] }" and unresolvableEntity()
  // -- the guard whose whole job is to catch that -- returned null for it.
  function ownEntity(table, name) {
    return Object.prototype.hasOwnProperty.call(table, name) ? table[name] : undefined;
  }

  function numericEntityValue(body) {
    var hex = body.charAt(1) === 'x' || body.charAt(1) === 'X';
    var code = parseInt(hex ? body.slice(2) : body.slice(1), hex ? 16 : 10);
    if (!isFinite(code) || code < 32 || code > 0x10FFFF ||
        (code >= 0xD800 && code <= 0xDFFF)) { return null; }
    return String.fromCodePoint(code);
  }

  // The one resolver. Returns null when this lane cannot render the reference,
  // which is what makes the clamp hold the prospect rather than show a reviewer
  // source text no page displays.
  function resolveEntity(body) {
    if (body.charAt(0) === '#') { return numericEntityValue(body); }
    // Exact lower or exact UPPER only. `&Lt;` is NOT `&lt;` -- HTML5 defines it as
    // U+226A -- so lowercasing any spelling rendered a different character than
    // the page shows, in the one string a reviewer is told to match.
    if (body === body.toLowerCase() || body === body.toUpperCase()) {
      var legacy = ownEntity(LEGACY_CI, body.toLowerCase());
      if (legacy !== undefined) { return legacy; }
    }
    var hit = ownEntity(DISPLAY_ENTITIES, body);
    return hit === undefined ? null : hit;
  }

  function scanPage(html, resolveAll) {
    var src = String(html === undefined || html === null ? '' : html);
    var chars = [];
    var at = [];
    var i = 0;
    var lowerSrc = null;
    function lower() {
      if (lowerSrc === null) { lowerSrc = src.toLowerCase(); }
      return lowerSrc;
    }
    while (i < src.length) {
      var c = src.charAt(i);
      if (c === '<') {
        // A COMMENT IS NOT PAGE TEXT. Terminating a tag at the first '>' meant a
        // commented-out block leaked its contents into page_text_normalized --
        // and commented-out markup always contains a '>'. A former staff entry
        // left in a comment, which is ordinary on a leadership page, was then
        // extractable, committable and quotable, and the reviewer was told to
        // find on the page a line no browser renders. Comments end at '-->'.
        if (src.slice(i, i + 4) === '<!--') {
          // HTML5 comment states, not just indexOf('-->'). `<!-->` and `<!--->`
          // are ABRUPT-CLOSING empty comments and `--!>` closes a comment too, so
          // treating them as unterminated swallowed the rest of a page a browser
          // renders in full -- fail-closed, but under exactly-five all-or-nothing
          // one such page can cost a whole run.
          var after = i + 4;
          if (src.slice(after, after + 1) === '>') { chars.push(' '); at.push(i); i = after + 1; continue; }
          if (src.slice(after, after + 2) === '->') { chars.push(' '); at.push(i); i = after + 2; continue; }
          var endComment = -1;
          for (var ci = after; ci < src.length; ci++) {
            if (src.charAt(ci) !== '-' || src.charAt(ci + 1) !== '-') { continue; }
            if (src.charAt(ci + 2) === '>') { endComment = ci + 3; break; }
            if (src.charAt(ci + 2) === '!' && src.charAt(ci + 3) === '>') { endComment = ci + 4; break; }
          }
          chars.push(' '); at.push(i);
          i = endComment === -1 ? src.length : endComment;
          continue;
        }
        var head = src.slice(i, i + 8).toLowerCase();
        if (head.indexOf('<script') === 0 || head.indexOf('<style') === 0) {
          var closeTag = head.indexOf('<script') === 0 ? '</script' : '</style';
          var closeAt = lower().indexOf(closeTag, i);
          var stop = closeAt === -1 ? -1 : src.indexOf('>', closeAt);
          chars.push(' '); at.push(i);
          i = (closeAt === -1 || stop === -1) ? src.length : stop + 1;
          continue;
        }
        var gt = src.indexOf('>', i);
        if (gt === -1) { chars.push(' '); at.push(i); i = src.length; continue; }
        var tag = src.slice(i, gt + 1);
        chars.push(BLOCK_CLOSE_RE.test(tag) || BLOCK_OPEN_RE.test(tag) ? '\n' : ' ');
        at.push(i);
        i = gt + 1;
        continue;
      }
      if (c === '&') {
        // resolveAll is the DISPLAY path only (see renderSpanForDisplay). The
        // model path resolves exactly the six names below and nothing else,
        // because page_text_normalized is the string the offset map is built over.
        if (resolveAll === true) {
          var ref = /^&(#\d{1,7}|#[xX][0-9a-fA-F]{1,6}|[a-zA-Z][a-zA-Z0-9]{1,31});/.exec(src.slice(i));
          if (ref !== null) {
            var resolved = resolveEntity(ref[1]);
            if (resolved !== null) {
              for (var rc = 0; rc < resolved.length; rc++) { chars.push(resolved.charAt(rc)); at.push(i); }
