        }
        var matched = null;
        for (var name in ENTITIES) {
          if (!Object.prototype.hasOwnProperty.call(ENTITIES, name)) { continue; }
          if (src.slice(i, i + name.length).toLowerCase() === name) { matched = name; break; }
