    }

    // Collapse whitespace runs to one space per line, trim each line, join with
    // newlines, then trim the whole -- all in one forward append, offsets riding
    // along. A newline's offset is -1: it exists only in the normalization.
    var textChars = [];
    var offsets = [];
    var lineStart = 0;          // index into textChars where the current line began
    var pendingSpace = false;
    var wroteLine = false;      // has any line been emitted yet
