      while (textChars.length > lineStart &&
             textChars[textChars.length - 1] === ' ') { textChars.pop(); offsets.pop(); }
      pendingSpace = false;
      // An EMPTY line emits nothing. `</li><li>` is a close and an open, so every
      // list item would otherwise be separated by a blank line -- harmless to the
      // clamp, but N19's reduced_text takes one line of context either side of a
      // match, and blank lines spend that budget on nothing.
      if (textChars.length === lineStart) { return; }
      wroteLine = true;
      textChars.push('\n'); offsets.push(-1);
      lineStart = textChars.length;
