    for (var n = 0; n < chars.length; n++) {
      var ch = chars[n];
      if (ch === '\n') { endLine(); continue; }
      if (isSpace(ch)) { pendingSpace = true; continue; }
      if (pendingSpace && textChars.length > lineStart) { textChars.push(' '); offsets.push(at[n]); }
      pendingSpace = false;
      textChars.push(ch); offsets.push(at[n]);
    }
    while (textChars.length > lineStart &&
           textChars[textChars.length - 1] === ' ') { textChars.pop(); offsets.pop(); }
    if (wroteLine === false && textChars.length === 0) {
      return { text: '', map: [], raw: src };
    }

    var lead = 0;
    while (lead < textChars.length && WS_RE.test(textChars[lead])) { lead++; }
    var tail = textChars.length;
    while (tail > lead && WS_RE.test(textChars[tail - 1])) { tail--; }
    return {
      text: textChars.slice(lead, tail).join(''),
      map: offsets.slice(lead, tail),
      raw: src
