  }

  function normalizePageHtml(html) { return scanPage(html).text; }

  // Given a span that is verbatim in the NORMALIZED text, return the exact raw
  // substring it came from -- or null when it cannot be located, which is a
  // fail-closed condition, never a fallback to the normalized string.
  //
  // A span can occur more than once (a name in a nav link and again in a bio).
  // The occurrences have DIFFERENT raw forms and therefore different lengths and
  // word counts, so which one is committed decides whether the ceilings are
  // cleared. Returning the first silently picks the most heavily marked-up one as
  // often as not, so all occurrences are derived and the SHORTEST raw form is
  // committed: it is equally verbatim, and it is the one a reviewer can read.
  function rawSpansFor(html, span) {
    var scanned = scanPage(html);
    var found = [];
    var from = 0;
    while (true) {
      var at = scanned.text.indexOf(span, from);
      if (at === -1) { break; }
      from = at + 1;
      var startAt = -1;
      var endAt = -1;
      for (var i = at; i < at + span.length; i++) {
        if (scanned.map[i] === -1) { continue; }
        if (startAt === -1) { startAt = scanned.map[i]; }
        endAt = scanned.map[i];
      }
      if (startAt === -1) { continue; }
      found.push(scanned.raw.slice(startAt, endAt + 1));
