  function rawSpanFor(html, span) {
    var all = rawSpansFor(html, span);
    if (all.length === 0) { return null; }
    var best = all[0];
    for (var i = 1; i < all.length; i++) {
      if (all[i].length < best.length) { best = all[i]; }
    }
    return best;
  }

  // DISPLAY ONLY. Never applied to page_text_normalized, never to quote_span.
  //
  // THE DISPLAY TEXT IS RENDERED FROM THE RAW COMMITTED BYTES, IN ONE PASS.
  //
  // The earlier design ran a second decode over page_text_normalized, and two
  // passes over the same text cannot be made to compose into one. Suppressing the
  // six names the normalizer resolves was not enough, because the normalizer's own
  // `&amp;` -> `&` MANUFACTURES a reference that did not exist in the source:
  // `&amp;#60;b&amp;#62;`, which a browser shows as the literal text `&#60;b&#62;`,
  // normalized to `&#60;b&#62;` and then decoded again to `<b>` -- a tag-shaped
  // string in a field documented as tag-free, handed to a reviewer under the
  // instruction "find this on the page". The second pass has no way to tell a `&`
  // the page printed from a `&` the first pass created.
  //
  // Rendering from `quote_span` -- the exact raw bytes that were committed --
  // removes the composition instead of trying to make it safe. Tags become spaces
  // or newlines by the same rules as the model path, every entity reference is
  // resolved exactly once, whitespace collapses, and the result is what a browser
  // displays for those bytes. There is no first pass to compose with.
