    }
    return null;
  }

  // What a browser displays for the committed raw bytes: tags out, every entity
  // resolved once, whitespace collapsed. One pass, over the source.
  function renderSpanForDisplay(rawSpan) {
    return scanPage(rawSpan, true).text;
