  var input = $input.first().json;
  var run = input.run;
  var config = input.config;

  // No default branch: anything but a boolean is a defect, not a value to
  // coerce.
  if (typeof input.cohort_complete !== 'boolean') {
    throw new Error('cohort-complete-not-boolean: ' + JSON.stringify(input.cohort_complete));
  }

  var files = [];
  function emit(relPath, text) {
    files.push({ file_path: run.out_dir + '/' + relPath, file_name: relPath.split('/').pop(), file_text: text });
  }
  function j2(obj) { return JSON.stringify(obj, null, 2) + '\n'; }

  // recheck_after for every code a prospect can carry. A code absent from the
  // table throws rather than defaulting: a ledger entry with an invented
  // interval means nothing to the next run.
  function recheckFor(reasonCode, outcome) {
    if (outcome === 'emitted') { return addDays(run.as_of, 3650); }
    if (outcome === 'carryover') { return run.as_of; }
    // ownProp, like every other table in this lane keyed by a value from
    // outside the node: `REASON_TABLE['constructor']` is a function, which is
    // truthy, so the unmapped throw below would be skipped and `row.days` would
    // be undefined -- a ledger entry with an interval of NaN.
    var row = ownProp(REASON_TABLE, reasonCode);
    if (!row) { throw new Error('reason-code-unmapped: ' + reasonCode); }
    return addDays(run.as_of, row.days);
  }
  function outcomeFor(reasonCode) {
    // ownProp, like every other table in this lane keyed by a value from
    // outside the node: `REASON_TABLE['constructor']` is a function, which is
    // truthy, so the unmapped throw below would be skipped and `row.days` would
    // be undefined -- a ledger entry with an interval of NaN.
    var row = ownProp(REASON_TABLE, reasonCode);
    if (!row) { throw new Error('reason-code-unmapped: ' + reasonCode); }
    return row.outcome;
