  var ledgerEntries = [];
  function ledgerAdd(p, outcome, reasonCode) {
    ledgerEntries.push({
      org_key: p.org_key,
      organization_name: p.organization_name,
      domain: p.org && p.org.host ? p.org.host : null,
      first_seen: run.as_of,
      last_evaluated: run.as_of,
      outcome: outcome,
      reason_code: reasonCode,
      recheck_after: recheckFor(reasonCode, outcome),
      run_id: run.run_id
