  var selected = input.selected || [];
  var surplus = input.surplus || [];
  var held = input.held || [];
  var rejected = input.rejected || [];
  var nearMatches = input.near_matches || [];
  var health = input.exclusion_health || {};

  if (input.cohort_complete) {
    for (var i = 0; i < selected.length; i++) {
      var p = selected[i];
      var ex = p.extracted;
      var org = p.org || {};
      var pages = Array.isArray(org.pages) ? org.pages : [];

      // Prefer the page a field was actually CITED from. N23 has already
      // rejected a citation whose purpose is wrong, so the cited page is always
      // of the right kind -- this makes the recorded source the exact page, not
      // merely a page of the right kind, which matters when an organization has
      // several signal or buyer pages and the model used the second one.
      var citedByPurpose = {};
      for (var fe = 0; fe < p.field_evidence.length; fe++) {
        var row = p.field_evidence[fe];
