      }

      var sources = [];
      for (var u = 0; u < PURPOSES.length; u++) {
        var pg = pageFor(PURPOSES[u]);
        if (!pg) { throw new Error('source-purpose-missing: ' + p.prospect_id + ' ' + PURPOSES[u]); }
        sources.push({
          source_id: 'src-' + p.prospect_id + '-' + SHORT[PURPOSES[u]],
          url: pg.url,
          snapshot_path: relPath(pg.snapshot_path),
          blob_oid: null,
          content_sha256: pg.content_sha256,
          retrieved_at: pg.retrieved_at,
          purpose: PURPOSES[u],
          http_status: pg.status,
          content_type: pg.content_type,
          byte_length: pg.byte_length
