      }

      var factOrg = 'fact-' + p.prospect_id + '-org-name';
      var factBuyerName = 'fact-' + p.prospect_id + '-buyer-name';
      var factBuyerTitle = 'fact-' + p.prospect_id + '-buyer-title';
      var factSignal = 'fact-' + p.prospect_id + '-signal';
      var factHyp = 'fact-' + p.prospect_id + '-hypothesis';

      // actors are null BY DESIGN: jt-ops requires builder, drafter and verifier
      // to be three distinct identities attested by a trusted owner. n8n is none
      // of them and must not name them; the binder refuses a pre-filled draft.
      var candidate = {
        schema_version: 'c2-discovery-candidate-draft-v1',
        binds_to: 'prospect-candidate-v2',
        prospect_id: p.prospect_id,
        cohort_id: run.cohort_id,
        segment: 'supportive-housing',
        burned_pool_reuse: false,
        actors: { builder_id: null, drafter_id: null },
        organization: { name: ex.organization_name, name_fact_id: factOrg },
        buyer: { name: ex.buyer_name, title: ex.buyer_title,
          name_fact_id: factBuyerName, title_fact_id: factBuyerTitle },
        signal: { fact_id: factSignal, event_type: ex.signal_event_type,
          event_date: ex.signal_event_date, source_id: 'src-' + p.prospect_id + '-signal' },
        hypothesis: { fact_id: factHyp, concept_id: ex.hypothesis.concept_id,
          question_concept_id: ex.hypothesis.question_concept_id },
        proof: { path: 'evidence/cohort-two.proof-asset.json',
          card_id: input.proof_card.card_id,
          fact_ids: input.proof_card.facts.map(function (f) { return f.fact_id; }) },
        sources: sources,
        structure: p.structure,
        unknowns: org.portfolio_units === 0 ? ['org-wide unit total not published'] : []
      };
      emit('prospects/' + p.prospect_id + '/candidate.draft.json', j2(candidate));

      var srcIdFor = { 'organization.name': 'org', 'buyer.name': 'buyer',
        'buyer.title': 'buyer', 'signal.event': 'signal' };
      var factIdFor = { 'organization.name': factOrg, 'buyer.name': factBuyerName,
        'buyer.title': factBuyerTitle, 'signal.event': factSignal };

      var evidence = {
        schema_version: 'c2-discovery-field-evidence-draft-v1',
        binds_to: 'prospect-field-verification-v2',
        receipt_id: 'recv-' + p.prospect_id + '-' + run.run_id,
        authority_rows: ['Prospect person/title', 'Organization identity/holdings', 'Proof wording'],
        verified_at: run.started_at,
        manifest_path: 'out/' + run.run_id + '/prospects/' + p.prospect_id + '/candidate.draft.json',
        manifest_blob_oid: null,
        // Genuinely circular: the manifest is candidate.draft.json, which the
        // binder rewrites (schema_version, blob OIDs, dropped draft-only keys)
        // before committing, so a hash computed here would never match the
        // committed bytes. The binder computes it over what it commits; this is
        // null by design rather than unimplemented, and section 7.6 already makes
        // the binder the authority for it.
        manifest_content_sha256: null,
        proof_path: 'evidence/cohort-two.proof-asset.json',
        proof_blob_oid: null,
        // Also null, for a different reason, and the difference matters. The
        // proof card IS committed verbatim, so its hash is meaningful -- but a
        // Code node cannot produce a SHA-256 (the task runner blocks require()
        // and subtle.digest is asynchronous, lesson #23), and every crypto node
        // in this workflow is already committed to other bytes. Computing it
        // would mean adding a node, which is an architecture change and not this
        // lane's to make. Section 7.6 makes the binder recompute it over the
        // committed file regardless, so the check still happens -- it happens
        // there rather than here. Listed in FINDINGS.md under "Still open" so it
        // is a known gap rather than a silent null.
        proof_content_sha256: null,
        source_bindings: sources.map(function (s) {
          return { source_id: s.source_id, path: s.snapshot_path, blob_oid: null,
            content_sha256: s.content_sha256, retrieved_at: s.retrieved_at };
        }),
        field_evidence: p.field_evidence.map(function (fe) {
          return { field: fe.field, fact_id: factIdFor[fe.field],
            source_id: 'src-' + p.prospect_id + '-' + srcIdFor[fe.field],
            quote_span: fe.quote_span, value_sha256: fe.value_sha256, confidence: 'confident' };
        }),
        // EXACTLY the signal fact id, and nothing else. The authority asserts
        // `set(basis_fact_ids) != {manifest["signal"]["fact_id"]}` and rejects
        // anything wider; the schema only requires minItems 1, so the previous
        // four-id list was schema-valid and unadmittable on every prospect.
        // Blueprint section 7.4 showed four and has been corrected too.
        inference_evidence: [{ fact_id: factHyp,
          basis_fact_ids: [factSignal],
          value_sha256: p.inference_evidence[0].value_sha256 }],
        allowed_proof_fact_ids: input.proof_card.facts.map(function (f) { return f.fact_id; })
      };
      emit('prospects/' + p.prospect_id + '/field-evidence.draft.json', j2(evidence));
      emit('prospects/' + p.prospect_id + '/gate-report.json', j2(p.gate_report));

      // ATTRIBUTION CONFIRMATION -- the control that replaces heuristic pairing.
      //
      // The clamp proves every value appears on a page of the right purpose. It
      // does not prove the buyer holds the title, that the date belongs to the
      // event, or that the organization operates supportive housing rather than
      // selling to it. A person decides those, against the cited page, and this
      // file carries exactly what they need and records what they decided.
      //
      // It ships `status: "unconfirmed"`. The binder refuses any prospect whose
      // confirmation is missing, unconfirmed or ambiguous -- per prospect, so one
      // unconfirmable organization blocks itself rather than the cohort.
      function evidenceFor(field) {
        for (var ef = 0; ef < p.field_evidence.length; ef++) {
          if (p.field_evidence[ef].field === field) { return p.field_evidence[ef]; }
        }
        return null;
      }
      // Every claim states what the machine ACTUALLY established about THAT
      // field, in that field's own words. A single shared sentence claimed "this
      // value is inside the span" for the two composite claims -- buyer
      // 'Name -- Title' and signal 'type on date' -- and neither composite was
      // ever checked as one string. A confirmation control whose own provenance
      // line is false is worse than no control: it is the sentence the reviewer
      // reads to decide how hard to look.
      function claim(question, field, value, proven, notProven) {
        var row = evidenceFor(field);
        return {
          question: question,
          // NOT decoded. An identity value cannot contain an entity reference
          // at all -- IDENTITY_RE has no ';', so one is rejected upstream as
          // identity-text-unsupported -- and signal.event's value is synthesized
          // from an enum and a date. So there is nothing to decode, and running
          // a decode here would be the second pass that F1 was about.
          asserted_value: value,
          // THE RECORD'S string, taken from the evidence row rather than from
          // the readable one. They differ for signal.event: the row carries
          // `type|date`, which is what value_sha256 covers and what admit
          // hashes, while the readable claim reads "type on date". Deriving
          // this from the display string made the field documented as
          // "byte-identical to field_evidence[].value" untrue for that claim --
          // the same class of defect as a provenance sentence that claims more
          // than the code does.
          committed_value: row ? row.value : null,
          // What a person will see on the page. The committed span is the raw
          // bytes, markup included, which nobody can find by eye.
          // No fallback to quote_span. A missing readable quote means the
          // evidence row lost it upstream, and substituting the raw span turns
          // "find this on the page" into markup nobody can find while the
          // provenance sentence still claims the value is inside it.
          // Rendered from the COMMITTED RAW BYTES in one pass -- not decoded
          // from readable_quote, which is already the product of one decode and
          // cannot be decoded again without compounding. This is what a browser
          // displays for exactly the bytes the record carries.
          quoted_text: row ? renderSpanForDisplay(row.quote_span) : null,
          committed_quote_span: row ? row.quote_span : null,
          source_url: row ? row.source_url : null,
          source_purpose: row ? row.source_purpose : null,
          snapshot_path: row ? relPath(row.source_path) : null,
          proven_automatically: proven,
          NOT_proven_automatically: notProven,
          confirmed: null
        };
      }

      var claims = {
        buyer_name: claim(
          'Is this a real person at this organization, named on that page?',
          'buyer.name', ex.buyer_name,
          'this name appears within the quoted span, on a page of purpose buyer-identity. ' +
          'The comparison folds case, width and accents (NFKC) and collapses whitespace, ' +
          'so it is verbatim up to that folding, not byte for byte.',
          'that the person works for this organization rather than being quoted, ' +
          'thanked, or listed as a partner or board member elsewhere on the page.'),
        buyer_title: claim(
          'Does this person hold this title?',
          'buyer.title', ex.buyer_title,
          'this title appears within the quoted span, on a page of purpose buyer-identity, ' +
          'verbatim up to NFKC folding and whitespace collapsing.',
          'that the title belongs to THIS person. Name and title are proven ' +
          'separately; nothing checks that they belong to each other, and a page ' +
          'listing several people offers many verbatim pairs that are false.'),
        organization: claim(
          'Is this the organization that operates the housing?',
          'organization.name', ex.organization_name,
          'this name appears within the quoted span, on a page of purpose ' +
          'organization-identity (verbatim up to NFKC folding and whitespace collapsing), ' +
          'and it normalizes to the organization key this run admitted.',
          'that the organization OPERATES supportive housing rather than selling to, ' +
          'funding or partnering with operators.'),
        signal: claim(
          'Does this date belong to this event?',
          'signal.event', ex.signal_event_type + ' on ' + ex.signal_event_date,
          'the quoted headline is verbatim on a page of purpose signal, and the date ' +
          ex.signal_event_date + ' appears somewhere on that same page.',
          'that the date belongs to THIS event rather than to another item on the ' +
          'same page. The event TYPE is a model label and is not checked against ' +
          'the page at all.')
      };

      emit('prospects/' + p.prospect_id + '/attribution-confirmation.json', j2({
        schema_version: 'c2-attribution-confirmation-v1',
        prospect_id: p.prospect_id,
        run_id: run.run_id,
        status: 'unconfirmed',
        confirmed_by: null,
        confirmed_at: null,
        notes: null,
        instructions: 'Open each source_url, find quoted_text on the page, and set confirmed ' +
          'to true or false on every claim. Then set status to "confirmed" (all true) ' +
          'or "rejected". A prospect left unconfirmed, or with any claim false or ' +
          'ambiguous, is not admissible and must not be bound.',
        claims: claims
      }));

      ledgerAdd(p, 'emitted', null);
    }

    // Every count is labelled with its denominator (lesson #137): "no email on
    // file" is two different numbers and they get conflated.
    var packet = [];
    packet.push('# Cohort two -- review packet');
    packet.push('');
    packet.push('Run `' + run.run_id + '`, as of ' + run.as_of + ', mode ' + run.mode + '.');
    packet.push('');
    packet.push('**No draft copy appears anywhere in this packet.** Copy is `jt-ops draft`,');
    packet.push('using its own prompt and gate chain. What follows is evidence for a decision.');
    packet.push('');
    for (var b = 0; b < selected.length; b++) {
      var sp = selected[b];
      var so = sp.org || {};
      var sex = sp.extracted;
      // THE PACKET MUST CITE THE PAGE THE DRAFT CITES.
      //
      // These three lookups used to run to the end of the list without breaking,
      // so they took the LAST page of each purpose while the candidate draft took
      // the page the value was actually cited from. They disagreed on every run:
      // the packet sent a reviewer to /staff ("Our staff directory is not
      // published online") to confirm a buyer extracted from /leadership.
      //
      // That is not a cosmetic bug. This packet is the only human check on
      // attribution, and the clamp can prove presence but NOT attribution.
      // Pointing the reviewer at a page that does not contain the fact removes
      // the one control that catches a crossed pairing.
      var spages = Array.isArray(so.pages) ? so.pages : [];
      var citedUrlByPurpose = {};
      for (var ce = 0; ce < sp.field_evidence.length; ce++) {
        var fr = sp.field_evidence[ce];
        if (fr.source_purpose && fr.source_url && !citedUrlByPurpose[fr.source_purpose]) {
          citedUrlByPurpose[fr.source_purpose] = fr.source_url;
        }
      }
      function packetPage(purpose) {
        var want = citedUrlByPurpose[purpose];
        if (want) {
          for (var w1 = 0; w1 < spages.length; w1++) {
            if (spages[w1].url === want) { return spages[w1]; }
          }
        }
        for (var w2 = 0; w2 < spages.length; w2++) {
          if (spages[w2].purpose === purpose) { return spages[w2]; }
        }
        return null;
      }
      var contact = packetPage('contact-surface');
      var buyerPage = packetPage('buyer-identity');
      var signalPage = packetPage('signal');
      var orgPage = packetPage('organization-identity');

      // The RENDER of the committed span -- the same thing the artifact shows,
      // from the same bytes. The raw span can carry '</strong>' through the
      // middle of a name, which is unfindable by eye; rendering the NORMALIZED
      // quote instead would decode a second time and show characters the page
      // never printed.
      function quoteFor(field) {
        for (var q1 = 0; q1 < sp.field_evidence.length; q1++) {
          var qr = sp.field_evidence[q1];
          if (qr.field === field) { return renderSpanForDisplay(qr.quote_span); }
        }
        return null;
      }
      packet.push('## ' + (b + 1) + '. ' + sex.organization_name);
      packet.push('');
      packet.push('- **Buyer:** ' + sex.buyer_name + ' -- ' + sex.buyer_title);
      packet.push('  - source: ' + (buyerPage ? buyerPage.url : '(none)') + ' (accessed ' + run.as_of + ')');
      // The exact text the extraction rests on. Without it there is nothing for a
      // reviewer to compare the page against, and "confirm the buyer" becomes a
      // judgement rather than a check.
      packet.push('  - name quoted: "' + (quoteFor('buyer.name') || '(none)') + '"');
      packet.push('  - title quoted: "' + (quoteFor('buyer.title') || '(none)') + '"');
      packet.push('  - **Confirm this person holds this title on that page.** The name and');
      packet.push('    the title are each proven verbatim on that page, separately. Nothing');
      packet.push('    checks that they belong to each other.');
      packet.push('- **Organization:** ' + sex.organization_name);
      packet.push('  - source: ' + (orgPage ? orgPage.url : '(none)'));
      packet.push('  - quoted: "' + (quoteFor('organization.name') || '(none)') + '"');
      packet.push('  - **Confirm this organization operates the housing.** Presence of the');
      packet.push('    name proves nothing about whether it operates, funds, or sells to');
      packet.push('    operators.');
      packet.push('- **Channel:** ' + sp.channel_address + ' (tier ' + sp.channel_tier + ')');
      packet.push('  - source: ' + (contact ? contact.url : '(none)'));
      packet.push('- **Signal:** ' + sex.signal_event_type + ' on ' + sex.signal_event_date +
        ' (' + sex.signal_age_days + ' days old)');
      packet.push('  - source: ' + (signalPage ? signalPage.url : '(none)'));
      packet.push('  - quoted: "' + (quoteFor('signal.event') || '(none)') + '"');
      packet.push('  - **Confirm that date belongs to that event.** The date is only checked');
      packet.push('    to be somewhere on the page, and the event type is not checked at all.');
      packet.push('- **Portfolio:** ' + so.portfolio_units + ' buildings matched in HPD registrations');
      packet.push('- **Proof fact ids:** ' + input.proof_card.facts.map(function (f) { return f.fact_id; }).join(', '));
      packet.push('- **Structure:** ' + sp.structure.opener_style + ' / ' +
        sp.structure.proof_placement + ' / ' + sp.structure.closing_form);
      packet.push('- **Unknowns:** ' + (so.portfolio_units === 0 ? 'org-wide unit total not published' : 'none'));
      packet.push('');
    }

    packet.push('## Near matches -- your call, in writing');
    packet.push('');
    if (nearMatches.length === 0) {
      packet.push('None this run.');
    } else {
      packet.push('| Organization | Matched against | Arm | Your call |');
      packet.push('|---|---|---|---|');
      for (var nm = 0; nm < nearMatches.length; nm++) {
        packet.push('| ' + nearMatches[nm].organization_name + ' | ' + nearMatches[nm].matched_against +
          ' | ' + nearMatches[nm].matched_arm + ' | |');
      }
    }
    packet.push('');
    packet.push('## Held');
    packet.push('');
    packet.push('| Organization | Reason | Re-check after |');
    packet.push('|---|---|---|');
    for (var hh = 0; hh < held.length; hh++) {
      packet.push('| ' + held[hh].organization_name + ' | ' + held[hh].reason_code + ' | ' +
        recheckFor(held[hh].reason_code, outcomeFor(held[hh].reason_code)) + ' |');
    }
    packet.push('');
    packet.push('## Exclusion-list health');
    packet.push('');
    packet.push('"0 organizations excluded" and "0 exclusion keys loaded" are different facts.');
    packet.push('');
    packet.push('- contact universe: ' + health.universe_records_usable + ' usable of ' +
      health.universe_records_loaded + ' loaded (' + health.universe_records_unusable + ' unusable)');
    packet.push('- ledger: ' + health.ledger_entries_usable + ' usable of ' + health.ledger_entries_loaded);
    packet.push('- protected clients: ' + health.protected_names_usable + ' usable of ' + health.protected_names_loaded);
    packet.push('');
    // Carryover is NOT an exclusion source and must not be counted as one: it
    // is a queue of prospects this run deliberately saved, and listing it under
    // exclusion health read as though those organizations had been screened out.
    packet.push('Carried forward (queued for the next run, NOT excluded): ' +
      health.carryover_usable + ' usable of ' + health.carryover_loaded);
    packet.push('');
    emit('review-packet.md', packet.join('\n') + '\n');

    for (var hp = 0; hp < held.length; hp++) {
      if (held[hp].reason_code !== 'segment-not-admissible') { continue; }
      // Flat, not `held/property-management/<org_key>.json`: N09D creates
      // out/<run_id>/ and out/<run_id>/prospects/<id>/snapshots/ and nothing
      // else, and readWriteFile write does not create parents (D11). A nested
      // path here would fail the write AFTER the snapshots are already on disk.
      emit('held-property-management-' + held[hp].org_key + '.json', j2({
        org_key: held[hp].org_key,
        organization_name: held[hp].organization_name,
        reason_code: 'segment-not-admissible',
        would_qualify_if: 'the segment enum in jt-ops/schemas/prospect_candidate.schema.json is extended',
        observed_at: run.as_of
      }));
    }
  } else {
    var report = [];
    report.push('# Cohort two -- short-cohort report');
    report.push('');
    report.push('Run `' + run.run_id + '`, as of ' + run.as_of + '.');
    report.push('');
    report.push('**No bundle was written.** ' + selected.length + ' organizations reached ADVANCE, ' +
      'and ' + input.required_cohort_size + ' are required. A partial cohort is not a partial win: ' +
      'jt-ops verify requires exactly ' + input.required_cohort_size + ' complete Git-bound drafts, ' +
      'so a short bundle is unusable rather than useful-but-smaller.');
    report.push('');
    report.push('## What blocked the rest');
    report.push('');
    var counts = {};
    for (var q2 = 0; q2 < held.length; q2++) {
      counts[held[q2].reason_code] = (counts[held[q2].reason_code] || 0) + 1;
    }
    for (var q3 = 0; q3 < rejected.length; q3++) {
      counts[rejected[q3].reason_code] = (counts[rejected[q3].reason_code] || 0) + 1;
    }
    var codes = Object.keys(counts).sort();
    if (codes.length === 0) { report.push('Nothing was evaluated this run.'); }
    for (var q4 = 0; q4 < codes.length; q4++) {
      report.push('- `' + codes[q4] + '`: ' + counts[codes[q4]] +
        ' of ' + input.records_processed + ' organizations processed');
    }
    report.push('');
    report.push('## Exclusion-list health');
    report.push('');
    report.push('- contact universe: ' + health.universe_records_usable + ' usable of ' +
      health.universe_records_loaded + ' loaded');
    report.push('- ledger: ' + health.ledger_entries_usable + ' usable of ' + health.ledger_entries_loaded);
    report.push('- protected clients: ' + health.protected_names_usable + ' usable of ' + health.protected_names_loaded);
    report.push('');
    emit('short-cohort-report.md', report.join('\n') + '\n');
  }

  for (var s2 = 0; s2 < surplus.length; s2++) { ledgerAdd(surplus[s2], 'carryover', null); }
  for (var h2 = 0; h2 < held.length; h2++) {
    ledgerAdd(held[h2], outcomeFor(held[h2].reason_code), held[h2].reason_code);
  }
  for (var r2 = 0; r2 < rejected.length; r2++) {
    ledgerAdd(rejected[r2], outcomeFor(rejected[r2].reason_code), rejected[r2].reason_code);
  }
  var frameSummary = input.frame_summary || { skipped: [], near_matches: [] };
  for (var sk = 0; sk < (frameSummary.skipped || []).length; sk++) {
    var s3 = frameSummary.skipped[sk];
    if (s3.reason_code === 'recheck-not-due' || s3.reason_code === 'max-orgs-per-run-cap') { continue; }
    ledgerEntries.push({
      org_key: s3.org_key, organization_name: s3.organization_name, domain: null,
      first_seen: run.as_of, last_evaluated: run.as_of,
      outcome: outcomeFor(s3.reason_code), reason_code: s3.reason_code,
      recheck_after: recheckFor(s3.reason_code, outcomeFor(s3.reason_code)), run_id: run.run_id
    });
  }
  for (var nm2 = 0; nm2 < nearMatches.length; nm2++) {
    ledgerEntries.push({
      org_key: nearMatches[nm2].org_key, organization_name: nearMatches[nm2].organization_name,
      domain: null, first_seen: run.as_of, last_evaluated: run.as_of,
      outcome: 'held', reason_code: 'near-match-requires-jt',
      recheck_after: recheckFor('near-match-requires-jt', 'held'), run_id: run.run_id
    });
  }

  // Carryover carries identity and reasons only -- never a channel value and
  // never a signal value. The copy standard forbids durable channel state, and
  // a carried-over signal would be reused without re-verification.
  var carryoverOut = {
    schema_version: 'c2-discovery-carryover-v1',
    prospects: surplus.map(function (s4) {
      return { org_key: s4.org_key, organization_name: s4.organization_name,
        carried_at: run.as_of, run_id: run.run_id, reason: 'surplus-above-cohort-size' };
    })
  };

  // A weekly run advances THROUGH the frame instead of re-scanning it, and
  // resets when a page comes back short because that is the end of the frame.
  var cursorBefore = $('N03 Validate Preflight').first().json.cursor;
  // What N09 saw on THIS page, and nothing else. It used to fall back to the
  // prior cursor's value, and N09 never supplied one -- so the field carried the
  // bootstrap null forever under a name that claims otherwise. An audit value
  // may be null (the page's last row had no date); it may not be inherited, and
  // it may not be missing.
  if (!Object.prototype.hasOwnProperty.call(frameSummary, 'last_registration_date_seen')) {
    throw new Error('frame-summary-missing-last-registration-date-seen');
  }
  var lastDateSeen = frameSummary.last_registration_date_seen;
  if (lastDateSeen !== null && !/^\d{4}-\d{2}-\d{2}$/.test(String(lastDateSeen))) {
    throw new Error('frame-summary-last-registration-date-malformed');
  }
  var rowsReturned = frameSummary.registrations_returned || 0;
  var cursorOut = {
    schema_version: 'c2-frame-cursor-v1',
    dataset: 'tesw-yqqr',
    offset: rowsReturned < config.frame.page_size ? 0 : cursorBefore.offset + rowsReturned,
    last_registration_date_seen: lastDateSeen,
    updated_at: run.started_at
  };

  if (files.length === 0) { throw new Error('artifact-set-empty'); }

  // ONLY file items leave this node -- N31 serializes and N32 writes every one
  // of them, so a non-file item here would be written as a file. The state
  // values ride on the first item the way N09's frame summary does, and N41
  // reads them by reference AFTER every remaining gate has passed.
  var out = files.map(function (f) { return { json: f }; });
  out[0].json._state_values = {
    artifact_count: files.length,
    ledger_entries: ledgerEntries,
    carryover: carryoverOut,
    cursor: cursorOut,
    records_written: input.cohort_complete ? selected.length : 0,
    records_skipped: (frameSummary.skipped || []).length,
    records_processed: input.records_processed,
    cohort_complete: input.cohort_complete
  };
  return out;
} catch (e) { throw new Error('N30: ' + e.message); }

// N33 Build Run Receipt + MC Payload -- convergence node.
//
// Hangs off N28, not off N32, so it still runs and still writes an honest
// receipt on a run that wrote nothing at all.
try {
  // Returns [] for a node that never executed this run. Never let a skipped
  // branch look the same as a branch that ran and produced nothing useful:
  // callers that need that distinction check the upstream counts instead.
  function outputOf(nodeName) {
    try { return $(nodeName).all(); } catch (e) { return []; }
  }

  var pre = $('N03 Validate Preflight').first().json;
  var sel = $('N28 Rank & Select Five').first().json;
  var run = pre.run;
  var config = pre.config;

  var emitted = outputOf('N30 Build Output Artifacts');
  var written = outputOf('N32 Write Artifacts');

  // The same integrity rule as N21's snapshot assertion: a receipt claiming
  // files that are not on disk is worse than no receipt.
  if (written.length !== emitted.length) {
    throw new Error('artifact-write-incomplete: ' + emitted.length + ' emitted, ' +
      written.length + ' written');
  }

  var state = null;
  for (var i = 0; i < emitted.length; i++) {
    if (emitted[i].json._state_values) { state = emitted[i].json._state_values; break; }
  }
  if (!state) { throw new Error('state-values-missing-from-artifacts'); }

  // run_receipt.schema.json calls these "repo-relative paths", so strip the
  // machine prefix rather than recording a path that means nothing off this box.
  function relPath(abs) {
    var root = config.paths.root;
    var at = String(abs).indexOf(root + '/');
    return at === -1 ? String(abs) : String(abs).slice(at + root.length + 1);
  }
  var outputs = [];
  for (var w = 0; w < written.length; w++) {
    if (typeof written[w].json.fileName === 'string') { outputs.push(relPath(written[w].json.fileName)); }
  }
  // Listed because this run is committed to writing them; N41..N43 write them
  // AFTER this node. A path listed here but absent on disk means the run died
  // after the receipt, which is exactly what the missing COMPLETE.json reports.
  outputs.push('state/discovery-ledger.json');
  outputs.push('state/carryover.json');
  outputs.push('state/frame-cursor.json');
  outputs.push('out/' + run.run_id + '/COMPLETE.json');

  var sourcesReached = ['data.cityofnewyork.us/resource/tesw-yqqr',
    'data.cityofnewyork.us/resource/feu5-w2e2'];
  var sourcesFailed = [];
  var pagesFetched = outputOf('N16B Normalize Page Fetch');
  var hostFailures = {};
  for (var p = 0; p < pagesFetched.length; p++) {
    var pj = pagesFetched[p].json;
    if (pj.fetch_ok || pj.fetch_reason === null) { continue; }
    if (pj.fetch_reason === 'transport-failure') { hostFailures[pj.host] = pj.error || 'transport failure'; }
  }
  for (var hk in hostFailures) {
    if (Object.prototype.hasOwnProperty.call(hostFailures, hk)) {
      sourcesFailed.push({ source: hk, error: String(hostFailures[hk]) });
    }
  }

  var recordsWritten = state.records_written;
  var degraded = sourcesFailed.length > 0;

  var status;
  if (recordsWritten === sel.required_cohort_size && !degraded) { status = 'ok'; }
  else if (recordsWritten === sel.required_cohort_size && degraded) { status = 'partial'; }
  else { status = 'empty'; }

  // Schema hard rule 1: zero records requires a reason. Without it a silent
  // pipeline and a broken pipeline look identical.
  var reason = null;
  if (recordsWritten === 0) {
    reason = sel.selected.length + ' of ' + sel.required_cohort_size +
      ' required prospects reached ADVANCE across ' + state.records_processed +
      ' organizations processed; no bundle written';
  }

  var notes = 'No external heartbeat is enabled yet; an unattended skipped run would look ' +
    'exactly like a quiet week until N43H is approved and un-disabled.';

  var receipt = {
    run_id: run.run_id,
    pipeline: 'cohort-two-prospect-discovery',
    started_at: run.started_at,
    finished_at: new Date().toISOString().replace(/\.\d+Z$/, 'Z'),
    status: status,
    degraded: degraded,
    reason: reason,
    records_written: recordsWritten,
    records_skipped: state.records_skipped,
    records_processed: state.records_processed,
    errors: [],
    sources_reached: sourcesReached,
    sources_failed: sourcesFailed,
    sources_unsupported: [
      { source: 'housingsearch.hcr.ny.gov',
        reason: 'JavaScript-rendered Salesforce application; not readable by plain HTTP' },
      { source: 'NYC Housing Connect',
        reason: 'JavaScript-rendered application; not readable by plain HTTP' }
    ],
    notes: notes,
    outputs: outputs,
    prompts: ['inline: N21 ORG_BLOCK builder'],
    model: config.model.id
  };

  // The card payload. cohortId, feedback, outreachReview, outreachDecision,
  // decidedBy, decidedAt, reviewCycle and snapshotSha256 are all FORBIDDEN on
  // create-only; clientId is silently dropped and discovery is not client-scoped.
  var card = {
    title: 'Cohort two: ' + recordsWritten + ' prospects ready to commit -- ' + run.run_id,
    firstAction: 'Open out/' + run.run_id + '/review-packet.md and confirm the five buyers against their cited primary-source URLs.',
    status: 'todo',
    assignee: config.mission_control.assignee,
    priority: config.mission_control.priority,
    lane: config.mission_control.lane,
    workstream: config.mission_control.workstream,
    project: 'AI Workflow Growth OS',
    whyItMatters: 'Cohort one M1s went out 2026-09-15. This is the next five. No draft copy exists yet and nothing can be sent until you commit the bundle and jt-ops runs admit-gate-draft-verify.',
    exactSteps: [
      'Open out/' + run.run_id + '/review-packet.md and read the five one-page briefs plus the near-match rows.',
      'Confirm each buyer name and title against its cited primary-source URL.',
      'Confirm each channel is the single published mailbox on the cited contact page.',
      'Approve or reject the cohort as a whole; a partial cohort is not usable downstream.',
      'If approved, run the binder against out/' + run.run_id + '/ and commit the five bundles to jt-ops.',
      'Run `jt-ops admit` against the resulting evidence commit.'
    ],
    pasteReadyPrompt: null,
    pasteDestination: config.paths.root + '/out/' + run.run_id + '/',
    doneState: 'Five bundles committed to jt-ops at a named commit, or the cohort explicitly rejected with the reason written into state/discovery-ledger.json.',
    evidenceLinks: [
      'out/' + run.run_id + '/review-packet.md',
      'out/' + run.run_id + '/run-receipt.json',
      'out/' + run.run_id + '/prospects/'
    ],
    sourceSystem: 'n8n-cohort-two-discovery',
    candidateId: run.run_id,
    dedupeKey: null,
    sourceHash: null,
    dollars: config.mission_control.dollars,
    stageProbability: config.mission_control.stage_probability,
    proofRequired: false,
    dueDate: Date.parse(run.as_of + 'T00:00:00Z') + 3 * 86400000,
    dueDateSource: 'self'
  };

  // Sorted keys, with sourceHash and dedupeKey omitted, so the hash is stable
  // across runs with identical content.
  function canonical(obj) {
    if (obj === null || typeof obj !== 'object') { return JSON.stringify(obj); }
    if (Array.isArray(obj)) { return '[' + obj.map(canonical).join(',') + ']'; }
    var keys = Object.keys(obj).filter(function (k) {
      return k !== 'sourceHash' && k !== 'dedupeKey';
    }).sort();
    return '{' + keys.map(function (k) {
      return JSON.stringify(k) + ':' + canonical(obj[k]);
    }).join(',') + '}';
  }

  return [
    { json: { file_path: run.out_dir + '/run-receipt.json', file_name: 'run-receipt.json',
      file_text: JSON.stringify(receipt, null, 2) + '\n',
      mc_card_payload: card, mc_payload_canonical_json: canonical(card),
      receipt: receipt, run: run } },
    { json: { file_path: run.out_dir + '/mc-card-payload.json', file_name: 'mc-card-payload.json',
      file_text: JSON.stringify(card, null, 2) + '\n',
      mc_card_payload: card, mc_payload_canonical_json: canonical(card),
      receipt: receipt, run: run } }
  ];
} catch (e) { throw new Error('N33: ' + e.message); }

// N39B Assert Create-Only.
//
// The writeMode attestation must be checked by something that can throw, which
// a NoOp cannot. buildTaskWriteResponse is the only thing that sets
// writeMode: "create-only", which is what makes this assertion meaningful
// rather than decorative.
//
// It also catches the disabled-node case: n8n passes items straight through a
// disabled node, so if write is true while N39 is still disabled the attestation
// is absent and the run fails closed instead of silently reporting a card that
// was never created.
try {
  var wanted = $('N03 Validate Preflight').first().json.config.mission_control.write === true;
  if (wanted && $input.item.json.writeMode !== 'create-only') {
    throw new Error('mc-write-mode-unconfirmed');
  }
  return $input.item;
} catch (e) { throw new Error('N39B: ' + e.message); }

// N41 Build Complete Marker -- runs last, and only if every side effect before
// it succeeded.
//
// r1 wrote a FAILED.json and asked the binder to refuse any directory containing
// one. That is not fail-closed: an execution killed by a restart, an OOM or a
// host sleep writes no marker at all, and the binder would have bound a
// half-written directory. ABSENCE of success is the safe signal.
//
// This is also the ONLY node that emits state. It is downstream of the artifact
// write, the receipt write and the Mission Control branch, so state advances
// only on a run where all three succeeded; a run that dies anywhere earlier
// leaves the last good state untouched and the next run re-derives from it.
try {
  // EVERY lookup whose key comes from outside this workflow goes through here.
  //
  // A bare object literal indexed with an external key resolves through
  // Object.prototype, so `constructor`, `toString`, `valueOf`, `hasOwnProperty`
  // and `__proto__` are truthy members of every table. That is not theoretical
  // here: the signal-type enum gate was `if (!HYPOTHESIS_TABLE[type])`, and it is
  // the ONLY enforcement of that enum -- the tool schema declares it but the model
  // API does not validate tool input -- so `signal_event_type: "__proto__"` was
  // ADMITTED, reached the review packet a person reads, and would have raised a
  // bare KeyError inside the authority's `RELATIONSHIPS[...]`, discarding all five
  // prospects after all five had been confirmed.
  function ownProp(table, key) {
    if (table === null || table === undefined) { return undefined; }
    var k = String(key === undefined || key === null ? '' : key);
    return Object.prototype.hasOwnProperty.call(table, k) ? table[k] : undefined;
  }

  // Returns [] for a node that never executed this run. Never let a skipped
  // branch look the same as a branch that ran and produced nothing useful:
  // callers that need that distinction check the upstream counts instead.
  function outputOf(nodeName) {
    try { return $(nodeName).all(); } catch (e) { return []; }
  }

  var pre = $('N03 Validate Preflight').first().json;
  var run = pre.run;
  var config = pre.config;

  var artifacts = outputOf('N30 Build Output Artifacts');
  var state = null;
  for (var i = 0; i < artifacts.length; i++) {
    if (artifacts[i].json._state_values) { state = artifacts[i].json._state_values; break; }
  }
  if (!state) { throw new Error('state-values-missing'); }

  var receiptItems = outputOf('N33 Build Run Receipt + MC Payload');
  var receipt = receiptItems.length ? receiptItems[0].json.receipt : null;
  if (!receipt) { throw new Error('receipt-missing'); }

  // If a card was supposed to be posted, the branch that posts it must have been
  // reached AND have asserted its attestation.
  var wantsCard = config.mission_control.write === true;
  var asserted = outputOf('N39B Assert Create-Only');
  if (wantsCard && asserted.length === 0) { throw new Error('mc-branch-not-reached'); }

  var written = outputOf('N32 Write Artifacts');
  var receiptWritten = outputOf('N36 Write Receipt + Payload');

  function j2(obj) { return JSON.stringify(obj, null, 2) + '\n'; }

  var ledgerOut = {
    schema_version: 'c2-discovery-ledger-v1',
    // The watermark advances ONLY on a run that reached this node. A decrease
    // would silently un-burn an organization already contacted (#134).
    exclusion_watermark: {
      universe_records: Math.max(
        pre.ledger.exclusion_watermark.universe_records,
        $('N06 Build Exclusion Index').first().json.exclusion_health.universe_records_loaded
      ),
      observed_at: run.started_at
    },
    entries: mergeLedger(pre.ledger.entries, state.ledger_entries)
  };
  // Written after the merge, from the merged length, and only ever upward --
  // the same Math.max discipline as the universe watermark, for the same reason.
  ledgerOut.exclusion_watermark.ledger_entries = Math.max(
    pre.ledger.exclusion_watermark.ledger_entries, ledgerOut.entries.length);

  // Latest wins, one entry per org_key.
  // An organization that has been EMITTED or CONTACTED stays that way.
  //
  // Latest-wins alone was wrong in one specific, reachable way: run 2 skips an
  // emitted organization as `burned-pool-duplicate` and N30 writes that back as
  // `outcome: 'rejected'`, which overwrote the `emitted` row -- and `rejected`
  // is not in {emitted, contacted}, so from run 3 the burned pool did not hold
  // the organization at all and the only thing left was a `recheck_after`
  // string comparison. Measured over three runs. A send is a fact about the
  // past and nothing a later run observes can undo it.
  function mergeLedger(existing, fresh) {
    // Declared INSIDE, because mergeLedger is called above where this block
    // appears: a `var` at the outer level hoists its name but not its value, so
    // the precedence list read `undefined` at the only moment it mattered.
    var TERMINAL = ['emitted', 'contacted'];
    function outcomeOf(e) {
      return String(e && e.outcome !== undefined && e.outcome !== null ? e.outcome : '')
        .trim().toLowerCase();
    }
    var byKey = {};
    var order = [];
    function put(e) {
      // A keyless entry is NOT skipped quietly: it would vanish from the next
      // write, and if it was a `contacted` row that is the record of a real send
      // being deleted. N03 refuses such a row before anything reaches here, so
      // arriving with one is a defect in the preflight, not an input.
      if (!e || typeof e !== 'object') { throw new Error('ledger-entry-not-an-object'); }
      if (typeof e.org_key !== 'string' || e.org_key.trim() === '') {
        throw new Error('ledger-entry-unkeyed: ' + JSON.stringify(e.org_key));
      }
      var prior = ownProp(byKey, e.org_key);
      if (prior !== undefined && TERMINAL.indexOf(outcomeOf(prior)) !== -1 &&
          TERMINAL.indexOf(outcomeOf(e)) === -1) {
        return;
      }
      // ownProp: a ledger entry keyed `constructor` is truthy on the prototype,
      // so it was written to byKey but never pushed to order -- silently dropped
      // from the next ledger write. That is the UN-BURN direction, the same one
      // N06's contact-universe-shrank guard exists to make fatal.
      if (ownProp(byKey, e.org_key) === undefined) { order.push(e.org_key); }
      byKey[e.org_key] = e;
    }
    for (var a = 0; a < (existing || []).length; a++) { put(existing[a]); }
    for (var b = 0; b < (fresh || []).length; b++) { put(fresh[b]); }
    return order.map(function (k) { return ownProp(byKey, k); });
  }

  var marker = {
    run_id: run.run_id,
    completed_at: new Date().toISOString().replace(/\.\d+Z$/, 'Z'),
    cohort_complete: state.cohort_complete,
    records_written: state.records_written,
    artifacts_written: written.length,
    receipt_files_written: receiptWritten.length,
    mc_card_posted: wantsCard && asserted.length > 0,
    receipt_path: run.out_dir + '/run-receipt.json',
    // Decision A. The workflow can produce a complete, self-consistent bundle
    // and STILL not have attribution confirmed -- that is a human step and this
    // records that it has not happened. The binder refuses a prospect whose
    // attribution-confirmation.json is missing, unconfirmed, or carries any
    // false or null claim, so an unconfirmable organization blocks itself rather
    // than the cohort.
    //
    // There is deliberately no `confirmations_present` count. This file is
    // written once, before any human has opened anything, so such a count is 0
    // in every run that will ever exist -- an inert number that reads like a
    // measurement. The requirement is stated instead, and the binder counts.
    attribution: {
      model: 'presence-only clamp plus explicit per-prospect human confirmation',
      confirmations_required: state.records_written,
      confirmed: false,
      artifact: 'prospects/<prospect_id>/attribution-confirmation.json',
      precondition: 'Each prospect is admissible only when its ' +
        'attribution-confirmation.json carries status "confirmed" and all four ' +
        'claims confirmed true. This file being present means the run produced ' +
        'its artifacts; it does not mean any prospect may be bound.'
    },
    state_files_written: [
      config.paths.root + '/state/discovery-ledger.json',
      config.paths.root + '/state/carryover.json',
      config.paths.root + '/state/frame-cursor.json'
    ],
    blueprint_revision: 'r4+D1/D3/D8/D11/D12'
  };

  // ORDER IS LOAD-BEARING: COMPLETE.json LAST.
  //
  // It is the binder's precondition -- a directory carrying it is committable.
  // N42/N43 write these in the order returned, so emitting it first would mean a
  // write failure part-way through leaves a directory marked complete whose
  // ledger never recorded the five as `emitted`. The next run would rediscover
  // them, G1 would not exclude them, and they would be re-emitted for outreach.
  // Writing it last makes the marker mean what it says: everything before it
  // succeeded.
  return [
    { json: { file_path: config.paths.root + '/state/discovery-ledger.json',
      file_name: 'discovery-ledger.json', file_text: j2(ledgerOut) } },
    { json: { file_path: config.paths.root + '/state/carryover.json',
      file_name: 'carryover.json', file_text: j2(state.carryover) } },
    { json: { file_path: config.paths.root + '/state/frame-cursor.json',
      file_name: 'frame-cursor.json', file_text: j2(state.cursor) } },
    { json: { file_path: run.out_dir + '/COMPLETE.json', file_name: 'COMPLETE.json', file_text: j2(marker) } }
  ];
} catch (e) { throw new Error('N41: ' + e.message); }
